  add('entree','Salade de concombre-tomate',10,'froid','concombre:1;tomate:2;huile:15;vinaigre:10','Couper concombre et tomates en dés. / Mélanger l’huile et le vinaigre puis verser sur les légumes.','🥗');
  add('entree','Salade carotte-pomme',10,'froid','carotte:250;pomme:1;citron:1','Râper les carottes et la pomme. / Arroser légèrement de jus de citron et mélanger.','🥕');
  add('entree','Salade de maïs et thon',10,'froid','mais:200;thon:120;tomate:2;huile:15','Égoutter maïs et thon. / Couper les tomates et mélanger le tout avec l’huile.','🥗');
  add('entree','Salade de lentilles',30,'casserole','lentilles:140;carotte:100;oignon:1;vinaigre:15;huile:15','Rincer les lentilles. / Cuire 20 à 25 minutes dans l’eau avec la carotte en dés, puis égoutter. / Ajouter l’oignon émincé, l’huile et le vinaigre.','🥗');
  add('entree','Salade de pois chiches',10,'froid','pois_chiches:250;tomate:2;oignon:1;citron:1;huile:15','Rincer et égoutter les pois chiches. / Ajouter tomates et oignon émincés. / Assaisonner avec citron et huile.','🥗');
  add('entree','Velouté de carottes',35,'casserole','carotte:400;pomme_terre:150;oignon:1;bouillon:1;creme:60','Éplucher et couper les légumes. / Cuire 25 minutes dans l’eau avec le bouillon. / Mixer finement avec la crème.','🥣');
  add('entree','Soupe de poireaux',35,'casserole','poireau:2;pomme_terre:200;bouillon:1;creme:40','Nettoyer les poireaux et couper les pommes de terre. / Couvrir d’eau, ajouter le bouillon et cuire 25 minutes. / Mixer puis ajouter la crème.','🥣');
  add('entree','Velouté de courgettes',30,'casserole','courgette:450;pomme_terre:150;oignon:1;bouillon:1','Couper légumes et oignon. / Cuire dans de l’eau avec le bouillon pendant 20 minutes. / Mixer et rectifier la texture.','🥣');
  add('entree','Soupe de potiron',35,'casserole','potiron:500;pomme_terre:150;oignon:1;creme:60','Faire revenir l’oignon dans une casserole avec un peu d’eau. / Ajouter courge et pomme de terre, couvrir d’eau, cuire 25 minutes puis mixer avec la crème.','🎃');
  add('entree','Tartines tomate-chèvre',12,'four','pain:4;tomate:2;chevre:90;huile:10','Préchauffer le four à 190 °C. / Disposer les tomates et le chèvre sur les tartines. / Arroser d’huile et gratiner environ 7 minutes.','🍞');
  add('entree','Salade d’avocat et tomates',10,'froid','avocat:1;tomate:3;citron:1;huile:15','Couper avocat et tomates en dés. / Arroser de citron et d’huile, remuer délicatement.','🥑');
  add('entree','Salade de riz froide',20,'casserole','riz:120;mais:100;tomate:2;thon:80;huile:15','Cuire le riz selon le paquet puis le refroidir rapidement. / Égoutter le thon et le maïs. / Mélanger avec les tomates et l’huile, conserver au frais.','🥗');
  add('entree','Petite salade de quinoa',20,'casserole','quinoa:120;concombre:1;tomate:2;citron:1','Rincer puis cuire le quinoa suivant le paquet. / Laisser tiédir, ajouter concombre et tomates. / Assaisonner au citron.','🥗');
  add('entree','Champignons à la crème',15,'poêle','champignon:300;creme:80;ail:8;huile:10','Nettoyer et émincer les champignons. / Les faire revenir avec l’ail dans l’huile pendant 8 minutes. / Ajouter la crème et chauffer 2 minutes.','🍄');
  add('entree','Salade pomme et noix',10,'froid','salade:120;pomme:1;noix:50;chevre:70','Laver la salade, couper la pomme. / Répartir le fromage et les noix, mélanger.','🥗');
  add('entree','Petits pois à la crème',15,'casserole','petits_pois:300;beurre:15;creme:40','Cuire les petits pois dans l’eau bouillante environ 8 minutes puis égoutter. / Ajouter le beurre et la crème, servir tiède.','🫛');
  // Plats (66)
  add('plat','Omelette jambon-fromage',12,'poêle','oeuf:4;jambon:2;fromage:65;beurre:12','Battre les œufs. / Faire revenir le jambon coupé en dés dans le beurre. / Verser les œufs, ajouter le fromage et plier quand l’omelette est prise.','🍳');
  add('plat','Omelette aux pommes de terre',25,'poêle','oeuf:4;pomme_terre:350;oignon:1;huile:20','Couper les pommes de terre en petits dés. / Les cuire avec l’oignon dans une poêle couverte jusqu’à tendreté. / Verser les œufs battus et laisser prendre des deux côtés.','🍳');
  add('plat','Omelette aux champignons',18,'poêle','oeuf:4;champignon:250;beurre:15;fromage:40','Faire revenir les champignons émincés dans le beurre. / Ajouter les œufs battus et le fromage. / Cuire doucement puis replier.','🍳');
  add('plat','Pâtes jambon-crème',20,'casserole','pates:180;jambon:2;creme:140;fromage:45','Cuire les pâtes selon l’emballage. / Réchauffer le jambon émincé dans la crème. / Égoutter les pâtes et les mélanger à la sauce et au fromage.','🍝');
  add('plat','Spaghetti bolognaise',35,'casserole','pates:180;boeuf:250;coulis:250;oignon:1;huile:15','Cuire les pâtes. / Faire revenir l’oignon et le bœuf dans l’huile. / Ajouter le coulis et laisser mijoter 15 minutes avant de servir sur les pâtes.','🍝');
  add('plat','Spaghetti tomate-basilic',20,'casserole','pates:180;coulis:240;ail:8;herbes:6;huile:15','Cuire les pâtes. / Chauffer le coulis avec ail et herbes dans l’huile 10 minutes. / Mélanger aux pâtes égouttées.','🍝');
  add('plat','Pâtes carbonara façon familiale',20,'casserole','pates:180;lardons:120;oeuf:2;parmesan:50','Cuire les pâtes. / Faire dorer les lardons. / Fouetter les œufs avec le parmesan ; hors du feu, mélanger aux pâtes chaudes puis incorporer les lardons.','🍝','Utiliser des œufs très frais ; servir immédiatement.');
  add('plat','Pâtes au thon et tomate',22,'casserole','pates:180;thon:140;coulis:240;oignon:1','Cuire les pâtes. / Faire mijoter l’oignon et le coulis 10 minutes. / Ajouter le thon égoutté, puis mélanger aux pâtes.','🍝');
  add('plat','Pâtes aux courgettes',25,'poêle','pates:180;courgette:300;creme:120;parmesan:35;huile:15','Cuire les pâtes. / Faire revenir les courgettes en demi-rondelles dans l’huile 10 minutes. / Ajouter crème, parmesan puis pâtes égouttées.','🍝');
  add('plat','Gratin de pâtes',35,'four','pates:200;creme:180;fromage:100;jambon:2','Préchauffer le four à 200 °C et cuire les pâtes al dente. / Mélanger les pâtes avec le jambon coupé, la crème et la moitié du fromage. / Répartir dans un plat, couvrir du reste du fromage et gratiner 15 minutes.','🧀');
  add('plat','Macaroni au fromage',25,'casserole','pates:200;lait:220;fromage:130;beurre:20;farine:20','Cuire les pâtes. / Fondre le beurre, ajouter la farine puis le lait petit à petit jusqu’à épaississement. / Faire fondre le fromage dans cette sauce et mélanger aux pâtes.','🧀');
  add('plat','Riz sauté aux légumes',20,'poêle','riz_cuit:350;carotte:160;petits_pois:120;oeuf:2;sauce_soja:25;huile:15','Faire revenir les carottes en petits dés dans l’huile jusqu’à tendreté. / Ajouter les petits pois puis le riz déjà cuit et bien chaud. / Brouiller les œufs dans un coin de la poêle, mélanger avec la sauce soja.','🍚','Utiliser du riz conservé rapidement au froid et bien réchauffé.');
  add('plat','Riz au poulet et carottes',30,'casserole','riz:160;poulet:260;carotte:200;oignon:1;huile:15','Cuire le riz selon le paquet. / Faire revenir le poulet coupé en petits morceaux avec l’oignon et les carottes. / Cuire complètement le poulet puis mélanger au riz.','🍚');
  add('plat','Risotto aux champignons',35,'casserole','riz:180;champignon:250;bouillon:1;oignon:1;beurre:20;parmesan:40','Faire revenir l’oignon et les champignons. / Ajouter le riz et verser progressivement environ 600 ml de bouillon chaud jusqu’à cuisson, en remuant. / Incorporer beurre et parmesan.','🍄','Préférer un riz à risotto si disponible.');
  add('plat','Riz à la tomate',25,'casserole','riz:180;coulis:220;oignon:1;huile:15','Faire revenir l’oignon dans l’huile. / Ajouter le riz, le coulis et de l’eau selon le riz utilisé. / Cuire à couvert jusqu’à absorption, en vérifiant la cuisson.','🍚');
  add('plat','Curry de poulet',35,'casserole','poulet:280;riz:160;creme:160;curry:8;oignon:1;huile:15','Cuire le riz. / Faire dorer le poulet avec l’oignon dans l’huile. / Ajouter curry et crème, laisser mijoter jusqu’à cuisson complète du poulet. / Servir avec le riz.','🍛');
  add('plat','Curry de pois chiches',25,'casserole','pois_chiches:300;coulis:220;creme:120;curry:8;riz:150','Cuire le riz. / Faire mijoter pois chiches rincés, coulis, crème et curry 15 minutes. / Servir sur le riz.','🍛');
  add('plat','Poulet rôti et pommes de terre',55,'four','poulet:350;pomme_terre:500;huile:25;herbes:5','Préchauffer le four à 200 °C. / Disposer le poulet et les pommes de terre coupées dans un plat, arroser d’huile et ajouter les herbes. / Cuire environ 40 à 45 minutes, jusqu’à cuisson complète du poulet.','🍗');
  add('plat','Poulet à la crème et champignons',35,'poêle','poulet:300;champignon:250;creme:180;oignon:1;huile:15','Faire revenir le poulet avec l’oignon et l’huile. / Ajouter les champignons, puis la crème. / Laisser mijoter jusqu’à cuisson complète du poulet et servir.','🍗');
  add('plat','Escalopes de poulet citron',25,'poêle','poulet:300;citron:1;beurre:20;riz:150','Cuire le riz. / Dorer les escalopes dans le beurre, vérifier leur cuisson complète. / Ajouter le jus de citron et servir avec le riz.','🍋');
  add('plat','Poulet aux courgettes',30,'poêle','poulet:280;courgette:360;creme:100;huile:15','Faire revenir le poulet émincé dans l’huile. / Ajouter les courgettes en dés et faire cuire à couvert. / Terminer par la crème et vérifier la cuisson complète du poulet.','🍗');
  add('plat','Quiche lorraine',45,'four','pate_brisee:1;lardons:160;oeuf:3;creme:200;lait:80','Préchauffer le four à 190 °C. / Faire dorer les lardons et les répartir sur la pâte dans un moule. / Fouetter œufs, crème et lait, verser puis cuire environ 30 minutes.','🥧');
  add('plat','Quiche jambon-fromage',45,'four','pate_brisee:1;jambon:3;oeuf:3;creme:180;fromage:100','Préchauffer le four à 190 °C. / Garnir la pâte de jambon et de fromage. / Verser le mélange œufs-crème et cuire 30 minutes environ.','🥧');
  add('plat','Quiche aux courgettes',45,'four','pate_brisee:1;courgette:300;oeuf:3;creme:160;fromage:80','Préchauffer le four à 190 °C. / Faire revenir les courgettes quelques minutes puis les répartir sur la pâte. / Verser œufs battus, crème et fromage puis cuire environ 30 minutes.','🥧');
  add('plat','Tarte tomate-moutarde',40,'four','pate_feuilletee:1;tomate:4;moutarde:25;fromage:90','Préchauffer le four à 200 °C. / Étaler la moutarde sur la pâte. / Disposer les tomates tranchées, parsemer de fromage et cuire environ 25 minutes.','🥧');
  add('plat','Pizza maison rapide',35,'four','pate_feuilletee:1;coulis:160;mozzarella:150;jambon:2;champignon:100','Préchauffer le four à 200 °C. / Étaler le coulis sur la pâte et ajouter les garnitures. / Cuire environ 20 à 25 minutes, jusqu’à pâte dorée.','🍕','Version rapide sur pâte feuilletée ; texture différente d’une pâte à pizza.');
  add('plat','Croque-monsieur',15,'poêle','pain:8;jambon:4;fromage:100;beurre:20','Garnir quatre sandwiches de jambon et de fromage. / Beurrer légèrement les faces extérieures. / Dorer 3 à 4 minutes de chaque côté dans une poêle, jusqu’à fromage fondu.','🥪');
  add('plat','Croque-madame',20,'poêle','pain:8;jambon:4;fromage:100;oeuf:2;beurre:20','Préparer et dorer quatre croques au jambon-fromage. / Cuire les œufs au plat séparément. / Servir avec un œuf sur une portion de croque par personne.','🍳');
  add('plat','Sandwich poulet-crudités',15,'froid','pain:4;poulet_cuit:200;salade:80;tomate:2;mayonnaise:35','Couper le poulet déjà cuit en fines lamelles. / Garnir le pain de salade, tomate, mayonnaise et poulet. / Servir bien frais.','🥪');
  add('plat','Wraps au thon',12,'froid','pain_wrap:4;thon:160;salade:90;tomate:2;mayonnaise:35','Mélanger le thon égoutté et la mayonnaise. / Garnir les tortillas avec la salade, la tomate et le thon. / Rouler et couper.','🌯');
  add('plat','Wraps au poulet',15,'froid','pain_wrap:4;poulet_cuit:220;salade:90;tomate:2;yaourt:1','Mélanger le yaourt avec des herbes selon le goût. / Garnir les tortillas de poulet déjà cuit, salade et tomate, puis rouler.','🌯');
  add('plat','Salade composée jambon-œuf',20,'casserole','salade:150;tomate:2;jambon:2;oeuf:2;mais:120;huile:15','Faire cuire les œufs 9 à 10 minutes puis les refroidir. / Laver la salade et couper les tomates. / Disposer jambon, œufs et maïs puis arroser d’huile.','🥗');
  add('plat','Salade de pâtes au thon',25,'casserole','pates:180;thon:140;tomate:2;mais:120;huile:15','Cuire puis refroidir rapidement les pâtes. / Égoutter le thon et le maïs. / Mélanger aux tomates coupées et assaisonner avec l’huile.','🥗');
  add('plat','Salade de riz aux œufs',25,'casserole','riz:160;oeuf:3;mais:120;tomate:2;huile:15','Cuire le riz et les œufs durs séparément. / Refroidir rapidement le riz et écaler les œufs. / Mélanger avec tomate, maïs et huile.','🥗');
  add('plat','Salade quinoa-avocat',25,'casserole','quinoa:160;avocat:1;tomate:2;concombre:1;citron:1','Cuire le quinoa et laisser tiédir. / Ajouter avocat, tomate et concombre en dés. / Assaisonner avec le jus du citron.','🥑');
  add("plat","Gratin dauphinois",70,"four","pomme_terre:750;creme:300;lait:120;ail:8;muscade:2;beurre:20","Préchauffer le four à 180 °C et beurrer un plat, le frotter avec l’ail. / Couper les pommes de terre en rondelles régulières de 2 à 3 mm sans les rincer. / Mélanger lait, crème et muscade puis verser sur les rondelles disposées en couches. / Enfourner 50 à 60 minutes, jusqu’à ce que le centre soit tendre et le dessus doré.","🥔","");
  add('plat','Gratin pomme de terre-jambon',55,'four','pomme_terre:600;jambon:3;creme:200;fromage:110','Préchauffer le four à 190 °C. / Précuire les pommes de terre en rondelles 10 minutes dans l’eau. / Alterner pommes de terre, jambon et crème ; couvrir de fromage et gratiner 30 minutes.','🥔');
  add('plat','Pommes de terre sautées aux lardons',30,'poêle','pomme_terre:550;lardons:150;oignon:1;huile:15','Couper les pommes de terre en petits dés. / Les faire revenir à couvert avec l’huile et l’oignon environ 20 minutes. / Ajouter les lardons et poursuivre jusqu’à cuisson complète.','🥔');
  add('plat','Poêlée pommes de terre et champignons',30,'poêle','pomme_terre:500;champignon:250;oignon:1;huile:20','Couper les pommes de terre en petits dés. / Faire revenir avec l’oignon et l’huile à couvert jusqu’à tendreté. / Ajouter les champignons puis cuire encore 8 minutes.','🍄');
  add('plat','Hachis parmentier',55,'four','pomme_terre:600;boeuf:300;oignon:1;lait:100;beurre:30;fromage:50','Préchauffer le four à 200 °C (chaleur traditionnelle) et beurrer légèrement un plat à gratin. / Éplucher les pommes de terre, les couper en morceaux et les cuire 20 à 25 minutes dans une casserole d’eau frémissante, jusqu’à ce qu’elles s’écrasent facilement à la fourchette. / Pendant ce temps, éplucher puis hacher l’oignon. Le faire revenir 4 minutes dans une poêle avec un peu de beurre, puis ajouter le bœuf haché. Cuire en remuant jusqu’à ce qu’il ne reste plus de partie crue. / Égoutter les pommes de terre, les écraser puis ajouter progressivement le lait chaud et le reste du beurre pour obtenir une purée souple. Saler et poivrer selon le goût. / Étaler la viande dans le plat, recouvrir de purée, lisser puis parsemer de fromage râpé. / Enfourner environ 18 à 20 minutes, jusqu’à ce que la surface soit dorée. Laisser reposer 5 minutes avant de servir.','🥔');
  add('plat','Boulettes de bœuf tomate',35,'poêle','boeuf:300;oeuf:1;chapelure:40;coulis:250;pates:150','Mélanger bœuf, œuf et chapelure puis former des boulettes. / Les faire cuire à cœur dans une poêle, ajouter le coulis et mijoter 10 minutes. / Servir avec les pâtes cuites.','🍝');
  add('plat','Steak et purée maison',35,'poêle','steak:2;pomme_terre:600;lait:100;beurre:25','Cuire les pommes de terre dans l’eau jusqu’à tendreté puis écraser avec lait et beurre. / Poêler les steaks selon le niveau de cuisson adapté. / Servir avec la purée.','🥩');
  add('plat','Chili doux au bœuf',35,'casserole','boeuf:250;haricots_rouges:300;coulis:240;oignon:1;mais:100;huile:15','Faire revenir le bœuf et l’oignon dans l’huile. / Ajouter haricots rincés, maïs et coulis. / Laisser mijoter 20 minutes en remuant.','🍲');
  add('plat','Chili végétarien',30,'casserole','haricots_rouges:320;mais:150;coulis:250;poivron:1;oignon:1;huile:15','Faire revenir le poivron et l’oignon coupés. / Ajouter haricots rincés, maïs et coulis. / Laisser mijoter 15 minutes.','🫘');
  add('plat','Lentilles aux carottes',35,'casserole','lentilles:180;carotte:220;oignon:1;bouillon:1','Rincer les lentilles. / Couper les légumes et cuire le tout dans de l’eau avec le bouillon pendant 25 à 30 minutes. / Égoutter si nécessaire.','🥕');
  add('plat','Poisson au citron et riz',30,'poêle','poisson:300;riz:160;citron:1;beurre:20','Cuire le riz selon le paquet. / Cuire le poisson à cœur dans le beurre, en le retournant délicatement. / Arroser de citron et servir avec le riz.','🐟');
  add('plat','Poisson au four et carottes',40,'four','poisson:320;carotte:350;huile:20;citron:1','Préchauffer le four à 190 °C. / Précuire les carottes 10 minutes dans l’eau. / Les placer avec le poisson dans un plat, arroser d’huile et citron puis cuire 15 à 20 minutes selon l’épaisseur.','🐟');
  add('plat','Saumon au four',30,'four','saumon:320;citron:1;riz:160;huile:10','Préchauffer le four à 190 °C. / Cuire le riz. / Déposer le saumon dans un plat avec citron et huile, enfourner 15 à 20 minutes jusqu’à cuisson à cœur.','🐟');
  add('plat','Saumon à la crème et pâtes',25,'poêle','saumon:260;pates:180;creme:150;citron:1','Cuire les pâtes. / Poêler le saumon jusqu’à cuisson complète et le détailler. / Ajouter la crème et un filet de citron, mélanger avec les pâtes.','🍝');
  add('plat','Crevettes à l’ail et riz',25,'poêle','crevettes:280;ail:10;riz:160;huile:20;citron:1','Cuire le riz. / Saisir les crevettes décortiquées et l’ail dans l’huile jusqu’à cuisson complète. / Arroser de citron et servir sur le riz.','🍤');
  add('plat','Poêlée courgettes et riz',25,'poêle','courgette:400;riz:170;oignon:1;huile:20;fromage:50','Cuire le riz. / Faire revenir oignon et courgettes dans l’huile jusqu’à tendreté. / Mélanger au riz et saupoudrer de fromage.','🍚');
  add('plat','Gratin de courgettes',45,'four','courgette:550;oeuf:2;creme:160;fromage:100','Préchauffer le four à 190 °C. / Faire dégorger les courgettes légèrement précuites. / Verser dans un plat, ajouter le mélange œufs-crème, parsemer de fromage et cuire 25 minutes.','🥒');
  add('plat','Poêlée de légumes au quinoa',30,'poêle','quinoa:170;courgette:250;carotte:200;poivron:1;huile:20','Cuire le quinoa selon le paquet. / Faire revenir les légumes en petits dés dans l’huile jusqu’à tendreté. / Mélanger et servir.','🥗');
  add('plat','Tortilla pommes de terre',30,'poêle','pomme_terre:450;oeuf:5;oignon:1;huile:25','Faire cuire les pommes de terre tranchées et l’oignon dans l’huile jusqu’à tendreté. / Mélanger aux œufs battus. / Cuire doucement en retournant la tortilla à l’aide d’une assiette.','🍳');
  add('plat','Galettes de pommes de terre',30,'poêle','pomme_terre:500;oeuf:1;farine:40;oignon:1;huile:25','Râper pommes de terre et oignon, presser pour retirer l’excédent d’eau. / Ajouter œuf et farine. / Cuire de petites galettes 4 à 5 minutes de chaque côté dans l’huile.','🥔');
  add('plat','Soupe-repas aux légumes',40,'casserole','pomme_terre:350;carotte:300;poireau:2;bouillon:1;pain:2','Éplucher et détailler les légumes. / Cuire 30 minutes dans une casserole d’eau avec le bouillon. / Mixer partiellement et servir avec le pain.','🥣');
  add('plat','Soupe-repas aux lentilles',40,'casserole','lentilles:190;carotte:200;oignon:1;coulis:150;bouillon:1','Faire revenir brièvement l’oignon. / Ajouter carottes, lentilles, coulis, eau et bouillon. / Cuire jusqu’à lentilles tendres, environ 30 minutes.','🥣');
  add('plat','Œufs cocotte à la crème',20,'four','oeuf:4;creme:100;fromage:50;pain:4','Préchauffer le four à 180 °C. / Verser la crème dans deux ramequins, casser les œufs et parsemer de fromage. / Cuire au bain-marie 10 à 12 minutes, selon la prise souhaitée, et servir avec pain.','🥚');
  add('plat','Œufs à la tomate',25,'poêle','oeuf:4;coulis:280;oignon:1;poivron:1;huile:15','Faire revenir oignon et poivron dans l’huile. / Ajouter le coulis et cuire 10 minutes. / Creuser quatre trous, casser les œufs et cuire à couvert jusqu’à ce que les blancs soient pris.','🍳');
  add('plat','Saucisses et lentilles',45,'casserole','saucisse:2;lentilles:200;carotte:170;oignon:1;bouillon:1','Faire cuire lentilles, carottes et oignon dans de l’eau avec le bouillon pendant 25 à 30 minutes. / Cuire les saucisses complètement selon leur type et les ajouter aux lentilles.','🍲');
  add('plat','Porc à la moutarde',35,'poêle','porc:300;moutarde:30;creme:140;riz:150','Cuire le riz. / Saisir le porc à la poêle et poursuivre la cuisson à cœur. / Ajouter crème et moutarde, laisser épaissir quelques minutes et servir.','🍲');
  add('plat','Rôti de porc aux pommes de terre',65,'four','porc:350;pomme_terre:500;oignon:1;huile:20','Préchauffer le four à 190 °C. / Déposer le porc avec pommes de terre, oignon et huile dans un plat. / Rôtir environ 50 minutes selon l’épaisseur, en vérifiant la cuisson à cœur.','🍖');
  add('plat','Poêlée de restes de pâtes',15,'poêle','pates_cuites:400;oeuf:2;fromage:70;huile:15','Réchauffer complètement les pâtes déjà cuites dans l’huile. / Ajouter les œufs battus, remuer jusqu’à cuisson. / Parsemer de fromage.','🍝','Utiliser des restes rapidement refroidis puis conservés au réfrigérateur.');
  add('plat','Riz sauté au poulet restant',18,'poêle','riz_cuit:350;poulet_cuit:200;petits_pois:120;sauce_soja:25;huile:15','Faire revenir les petits pois dans l’huile. / Ajouter le riz et le poulet déjà cuits ; réchauffer complètement. / Ajouter la sauce soja et servir aussitôt.','🍚','Restes refroidis rapidement, conservés au froid et réchauffés correctement.');
  add('plat','Croquettes de riz au fromage',25,'poêle','riz_cuit:360;oeuf:2;fromage:90;chapelure:60;huile:25','Mélanger le riz froid, les œufs et le fromage. / Former des galettes et les passer dans la chapelure. / Dorer de chaque côté dans l’huile jusqu’à cœur bien chaud.','🍚');
  add('plat','Riz crémeux aux champignons',20,'poêle','riz_cuit:360;champignon:220;creme:120;fromage:50','Cuire les champignons émincés à la poêle. / Ajouter le riz déjà cuit, réchauffer complètement et incorporer la crème. / Terminer avec le fromage.','🍄');
  add('plat','Pommes de terre farcies au jambon',55,'four','pomme_terre:600;jambon:2;creme:100;fromage:90','Préchauffer le four à 200 °C. / Cuire les pommes de terre entières environ 40 minutes jusqu’à tendreté. / Les ouvrir, garnir de jambon, crème et fromage, puis gratiner 8 minutes.','🥔');
  // Desserts (26)
  add('dessert','Salade de fruits',10,'froid','pomme:1;banane:1;orange:2;kiwi:2','Éplucher et couper les fruits en morceaux réguliers. / Mélanger dans un saladier et servir frais.','🍓');
  add('dessert','Pommes au four',35,'four','pomme:2;beurre:20;miel:30;cannelle:2','Préchauffer le four à 180 °C. / Évider les pommes, garnir de beurre, miel et cannelle. / Cuire environ 25 minutes jusqu’à tendreté.','🍎');
  add('dessert','Compote de pommes maison',25,'casserole','pomme:4;sucre:25;cannelle:2','Peler et couper les pommes. / Faire compoter à couvert avec un peu d’eau 15 à 20 minutes. / Ajouter le sucre et la cannelle, écraser selon la texture souhaitée.','🍏');
  add('dessert','Bananes poêlées au miel',10,'poêle','banane:2;beurre:15;miel:30','Couper les bananes dans la longueur. / Les dorer doucement dans le beurre, puis ajouter le miel en fin de cuisson.','🍌');
  add('dessert','Yaourt miel et noix',5,'froid','yaourt:2;miel:30;noix:40','Verser les yaourts dans deux bols. / Ajouter le miel et les noix concassées.','🍯');
  add('dessert','Mousse au chocolat',20,'froid','chocolat:120;oeuf:3','Faire fondre le chocolat puis le laisser tiédir. / Séparer les œufs, incorporer les jaunes au chocolat. / Monter les blancs en neige et les incorporer délicatement. / Réserver au froid au moins 3 heures.','🍫','Contient des œufs crus : déconseillé aux personnes à risque ; utiliser une recette avec œufs pasteurisés au besoin.');
  add('dessert','Crème chocolat',20,'casserole','lait:400;chocolat:100;sucre:30;farine:25','Chauffer doucement le lait et le chocolat. / Délayer farine et sucre dans un peu de lait froid, ajouter en fouettant. / Cuire à feu doux jusqu’à épaississement puis laisser refroidir.','🍫');
  add('dessert','Riz au lait',45,'casserole','riz:110;lait:500;sucre:50;vanille:2','Verser riz, lait et vanille dans une casserole. / Cuire à feu doux 35 à 40 minutes en remuant souvent. / Ajouter le sucre en fin de cuisson et laisser tiédir.','🍚');
  add('dessert','Semoule au lait',15,'casserole','semoule:75;lait:450;sucre:45;vanille:2','Chauffer le lait avec la vanille. / Verser la semoule en pluie et remuer 5 à 7 minutes selon le produit. / Sucrer puis répartir dans deux bols.','🥣');
  add('dessert','Crêpes au sucre',25,'poêle','farine:130;lait:260;oeuf:2;beurre:15;sucre:40','Préparer une pâte lisse avec farine, œufs, lait et beurre fondu. / Cuire les crêpes à la poêle. / Saupoudrer de sucre au moment de servir.','🥞');
  add('dessert','Crêpes chocolat',25,'poêle','farine:130;lait:260;oeuf:2;beurre:15;chocolat:80','Préparer la pâte et cuire les crêpes. / Faire fondre le chocolat au bain-marie. / Napper les crêpes de chocolat fondu.','🥞');
  add('dessert','Pain perdu sucré',15,'poêle','pain:4;oeuf:2;lait:130;sucre:40;beurre:20','Fouetter œufs, lait et sucre. / Tremper le pain puis cuire à la poêle dans le beurre jusqu’à dorure des deux côtés.','🍞');
  add('dessert','Mug cake chocolat',10,'micro-ondes','farine:50;sucre:35;cacao:20;lait:65;huile:20;levure:3','Mélanger les ingrédients dans deux grandes tasses adaptées au micro-ondes. / Cuire par intervalles de 30 secondes, environ 1 à 2 minutes selon la puissance. / Laisser tiédir et vérifier la cuisson.','🍫');
  add('dessert','Gâteau au yaourt miniature',40,'four','yaourt:1;farine:120;sucre:90;oeuf:2;huile:45;levure:6','Préchauffer le four à 180 °C. / Mélanger yaourt, œufs, sucre puis farine, levure et huile. / Verser dans un petit moule et cuire environ 25 à 30 minutes, jusqu’à lame sèche.','🍰');
  add('dessert','Fondant chocolat individuel',25,'four','chocolat:100;beurre:70;oeuf:2;sucre:60;farine:35','Préchauffer le four à 180 °C. / Fondre chocolat et beurre, ajouter œufs, sucre et farine. / Verser dans deux ramequins et cuire environ 12 à 15 minutes selon la texture souhaitée.','🍫');
  add('dessert','Cookies chocolat',25,'four','farine:130;beurre:65;sucre:70;oeuf:1;chocolat:80;levure:3','Préchauffer le four à 180 °C. / Mélanger beurre mou et sucre, puis œuf, farine, levure et chocolat haché. / Former de petits tas et cuire 10 à 12 minutes.','🍪');
  add('dessert','Crumble aux pommes',40,'four','pomme:3;farine:100;beurre:65;sucre:70;cannelle:2','Préchauffer le four à 180 °C. / Mettre les pommes coupées dans un petit plat. / Sabler farine, beurre et sucre du bout des doigts, répartir sur les fruits et cuire 25 minutes.','🍎');
  add('dessert','Tarte fine aux pommes',35,'four','pate_feuilletee:1;pomme:3;sucre:35;beurre:20','Préchauffer le four à 200 °C. / Étaler la pâte, disposer de fines tranches de pomme. / Parsemer de sucre et de noisettes de beurre puis cuire 20 à 25 minutes.','🥧');
  add('dessert','Poires au chocolat',15,'casserole','poire:2;chocolat:90;lait:40','Peler et couper les poires. / Faire fondre doucement le chocolat avec le lait. / Napper les poires et servir.','🍐');
  add('dessert','Verrine fromage blanc-framboises',5,'froid','fromage_blanc:300;framboise:160;miel:30','Répartir le fromage blanc dans deux verrines. / Ajouter les framboises puis le miel.','🍓');
  add('dessert','Verrine banane-biscuit',8,'froid','banane:2;yaourt:2;biscuit:60;chocolat:30','Écraser grossièrement les biscuits et couper les bananes. / Alterner yaourt, banane et biscuits. / Parsemer de chocolat râpé.','🍌');
  add('dessert','Salade orange-cannelle',8,'froid','orange:3;miel:20;cannelle:2','Peler les oranges à vif et couper en rondelles. / Ajouter le miel et une pincée de cannelle.','🍊');
  add('dessert','Yaourt pomme caramélisée',12,'poêle','pomme:2;yaourt:2;beurre:15;sucre:25','Couper les pommes en dés puis les faire dorer dans le beurre avec le sucre. / Servir tièdes sur les yaourts.','🍏');
  add('dessert','Bananes au chocolat',10,'casserole','banane:2;chocolat:80;noix:30','Couper les bananes dans deux bols. / Faire fondre le chocolat et le verser sur les fruits. / Ajouter les noix concassées.','🍌');
  add('dessert','Fruits rouges façon crumble minute',10,'poêle','fraise:160;framboise:100;biscuit:70;yaourt:2','Rincer les fruits et les couper si nécessaire. / Émietter les biscuits. / Servir les fruits sur les yaourts et parsemer de biscuits.','🍓');
  add('dessert','Pomme et raisins secs tièdes',12,'poêle','pomme:2;raisins_secs:50;beurre:15;cannelle:2','Faire revenir les pommes en dés dans le beurre. / Ajouter les raisins secs et une pincée de cannelle. / Cuire jusqu’à tendreté et servir tiède.','🍎');
  // Recettes adaptées aux équipements V0.2, avec temps et portions indicatifs.
  add('petit','Gaufres maison',25,'gaufrier','farine:180;lait:200;oeuf:2;beurre:35;sucre:25;levure:7','Faire fondre le beurre. / Mélanger farine, levure, sucre, œufs et lait puis le beurre. / Verser une louche dans le gaufrier préchauffé et cuire jusqu’à ce que les gaufres soient dorées.','🧇');
  add('plat','Frites maison à la friteuse',35,'friteuse','pomme_terre:700;huile:300','Éplucher les pommes de terre et les couper en bâtonnets. / Les rincer, bien les sécher et faire chauffer la friteuse selon sa notice. / Frire en petites quantités jusqu’à cuisson et coloration souhaitées, puis égoutter sur papier absorbant. Attention aux projections d’huile.','🍟','La quantité d’huile incluse correspond à un besoin indicatif, pas forcément à l’huile consommée. Adapter au niveau de remplissage et à la notice de la friteuse.');
  add('plat','Raclette classique',30,'raclette','pomme_terre:650;fromage:400;jambon:4;cornichon:100','Faire cuire les pommes de terre dans l’eau jusqu’à tendreté. / Disposer jambon, fromage et cornichons sur la table. / Faire fondre le fromage dans les coupelles de l’appareil à raclette et servir avec les pommes de terre.','🧀');
  add('dessert','Crêpes sucrées à la crêpière',30,'crêpière','farine:150;lait:300;oeuf:2;sucre:20;beurre:20','Fouetter farine, lait, œufs et sucre pour obtenir une pâte lisse. / Ajouter le beurre fondu et laisser reposer 10 minutes si possible. / Cuire chaque crêpe sur la crêpière légèrement graissée selon la notice, puis déguster.','🥞');
  // V0.3 — nouvelles recettes conçues pour Frigo Express (quantités pour deux personnes).
  add("petit","Tartines ricotta et miel",7,"froid","pain:4;ricotta:120;miel:25;noix:30","Faire griller les tranches de pain juste avant de servir. / Étaler la ricotta, répartir les noix concassées. / Ajouter le miel au dernier moment pour garder le pain croustillant.","🍯","");
  add("petit","Porridge pomme-cannelle",12,"casserole","flocons:100;lait:300;pomme:2;cannelle:2;miel:15","Couper les pommes en tout petits dés. / Chauffer le lait avec les flocons en remuant 6 minutes à feu doux. / Ajouter les pommes et la cannelle, poursuivre 3 minutes, puis servir avec le miel.","🥣","");
  add("petit","Bol de fromage blanc kiwi-amandes",7,"froid","fromage_blanc:300;kiwi:2;amandes:40;miel:15","Éplucher les kiwis et les couper en demi-rondelles. / Répartir le fromage blanc dans les bols. / Ajouter les kiwis, les amandes concassées puis le miel.","🥝","");
  add("petit","Tartines avocat-tomate",10,"froid","pain:4;avocat:1;tomate:2;citron:1","Faire griller le pain. / Écraser l’avocat avec un peu de jus de citron. / Étaler, ajouter les tranches de tomate et servir sans attendre.","🥑","");
  add("petit","Brioche perdue à la cannelle",15,"poêle","brioche:4;oeuf:2;lait:140;sucre:20;cannelle:2;beurre:20","Battre les œufs, le lait, le sucre et la cannelle. / Tremper brièvement les tranches de brioche pour les imbiber sans les casser. / Dorer dans le beurre 2 minutes de chaque côté, servir tiède.","🍞","");
  add("petit","Smoothie poire-vanille",6,"froid","poire:2;yaourt:2;lait:150;vanille:2","Éplucher les poires et retirer les pépins. / Mixer avec les yaourts, le lait et la vanille. / Ajouter un peu de lait si le mélange est trop épais, servir frais.","🥤","");
  add("petit","Pancakes chocolat-banane",20,"poêle","banane:2;farine:130;oeuf:2;lait:100;cacao:15;levure:5","Écraser une banane et la mélanger aux œufs et au lait. / Incorporer farine, cacao et levure sans trop travailler la pâte. / Cuire de petites portions 2 minutes par face et servir avec la seconde banane coupée.","🥞","");
  add("petit","Œufs brouillés aux épinards",12,"poêle","oeuf:4;epinards:120;lait:40;beurre:15","Faire tomber les épinards dans une poêle chaude jusqu’à évaporation de leur eau. / Fouetter les œufs avec le lait. / Baisser le feu, ajouter le beurre puis les œufs et remuer jusqu’à ce qu’ils soient pris.","🍳","");
  add("petit","Toast chèvre et pomme",10,"froid","pain:4;chevre:100;pomme:1;miel:20","Griller légèrement le pain. / Émincer la pomme finement en retirant les pépins. / Tartiner de chèvre et disposer les lamelles de pomme puis le miel.","🍏","");
  add("petit","Salade de fruits orange-kiwi",10,"froid","orange:2;kiwi:2;pomme:1;citron:1","Peler les oranges et les kiwis. / Couper tous les fruits en morceaux de taille proche. / Ajouter quelques gouttes de citron et mélanger délicatement.","🍊","");
  add("petit","Omelette tomate-basilic",14,"poêle","oeuf:4;tomate:2;herbes:4;huile:10","Couper les tomates en dés et retirer leur excès de jus. / Battre les œufs avec les herbes. / Faire sauter les tomates 2 minutes puis verser les œufs et cuire à feu modéré.","🍳","");
  add("petit","Bol avoine et poire",8,"froid","flocons:90;poire:2;fromage_blanc:260;noix:30","Couper les poires en petits cubes. / Répartir le fromage blanc et les flocons dans les bols. / Ajouter les poires et les noix au dernier moment.","🥣","");
  add("petit","Chocolat chaud maison et tartines",10,"casserole","lait:400;chocolat:80;pain:4","Chauffer doucement le lait dans une casserole sans le faire bouillir. / Ajouter le chocolat haché et fouetter jusqu’à dissolution. / Servir avec le pain grillé, en vérifiant la température de la boisson.","🍫","");
  add("petit","Gaufres à la pomme",28,"gaufrier","farine:155;lait:180;oeuf:2;pomme:1;levure:6;beurre:30","Râper la pomme et presser légèrement son jus. / Fouetter œufs et lait, ajouter farine et levure puis le beurre fondu et la pomme. / Verser dans le gaufrier préchauffé et cuire selon sa notice jusqu’à dorure.","🧇","");
  add("petit","Crêpes à la compote",25,"crêpière","farine:130;lait:250;oeuf:2;beurre:20;compote:180","Mélanger farine, œufs et lait jusqu’à pâte lisse, incorporer le beurre fondu. / Faire chauffer et graisser légèrement la crêpière. / Cuire les crêpes une par une et les garnir de compote.","🥞","");
  add("petit","Tartines ricotta-framboise",7,"froid","pain:4;ricotta:120;framboise:140;miel:20","Griller les tranches de pain et les laisser tiédir. / Étaler la ricotta. / Poser délicatement les framboises puis ajouter quelques gouttes de miel.","🍓","");
  add("petit","Yaourt à la banane et aux noix",5,"froid","yaourt:2;banane:2;noix:35;cannelle:2","Éplucher les bananes et les couper en rondelles. / Répartir les yaourts et les bananes. / Terminer avec les noix concassées et une pincée de cannelle.","🥣","");
  add("petit","Mini-sandwich œuf-fromage",15,"poêle","pain:4;oeuf:2;fromage:60;beurre:10","Faire cuire les œufs en omelette fine dans une poêle beurrée. / Couper l’omelette en deux et la poser sur deux tranches de pain. / Ajouter le fromage, refermer puis réchauffer 2 minutes de chaque côté.","🥪","");
  add("petit","Porridge au chocolat et poire",12,"casserole","flocons:100;lait:300;cacao:15;poire:2","Chauffer les flocons et le lait 6 à 8 minutes en remuant. / Ajouter le cacao et mélanger jusqu’à disparition des grumeaux. / Servir avec les poires coupées en dés.","🍐","");
  add("petit","Bol agrumes et fromage blanc",8,"froid","fromage_blanc:300;orange:2;kiwi:1;amandes:30","Prélever les quartiers d’orange sans peau blanche. / Éplucher le kiwi puis le couper. / Répartir les fruits sur le fromage blanc et parsemer d’amandes.","🍊","");
  add("entree","Velouté de carottes au curry",35,"casserole","carotte:450;pomme_terre:130;oignon:1;curry:5;creme:70","Éplucher carottes et pomme de terre puis couper en dés. / Faire revenir l’oignon avec un peu d’eau, ajouter les légumes et couvrir à hauteur. / Cuire 25 minutes, mixer et incorporer curry puis crème.","🥕","");
  add("entree","Salade de lentilles à la moutarde",25,"casserole","lentilles:150;carotte:120;echalote:1;moutarde:15;huile:15","Rincer les lentilles puis cuire selon leur emballage sans les laisser éclater. / Égoutter, laisser tiédir et ajouter carotte râpée et échalote hachée. / Fouetter moutarde et huile puis assaisonner.","🥗","");
  add("entree","Houmous maison au citron",10,"froid","pois_chiches:260;citron:1;ail:5;huile:25;paprika:2","Rincer puis égoutter les pois chiches. / Les mixer avec le jus de citron, l’ail, l’huile et un peu d’eau jusqu’à texture souple. / Saupoudrer de paprika, garder au frais jusqu’au service.","🫘","");
  add("entree","Velouté de courgettes au chèvre",30,"casserole","courgette:500;pomme_terre:150;chevre:80;oignon:1","Couper courgettes, pomme de terre et oignon en morceaux. / Couvrir d’eau dans une casserole et faire mijoter environ 20 minutes. / Mixer, incorporer le chèvre et réchauffer doucement.","🥒","");
  add("entree","Tomates farcies au thon froides",15,"froid","tomate:4;thon:170;fromage_blanc:90;citron:1;herbes:4","Découper le chapeau des tomates et retirer délicatement les graines. / Mélanger thon égoutté, fromage blanc, citron et herbes. / Garnir les tomates et réserver au frais jusqu’au service.","🍅","");
  add("entree","Carpaccio de courgettes au citron",12,"froid","courgette:300;citron:1;huile:20;parmesan:30","Laver la courgette et la trancher très finement. / Disposer les lamelles sur un plat puis arroser d’huile et de jus de citron. / Parsemer de parmesan juste avant de servir.","🥒","");
  add("entree","Salade betterave-chèvre et noix",10,"froid","betterave:250;chevre:90;noix:35;huile:15;vinaigre:10","Couper les betteraves cuites en petits cubes. / Émietter le chèvre et concasser les noix. / Mélanger avec l’huile et le vinaigre au moment de servir.","🥗","");
  add("entree","Soupe tomate-poivron",30,"casserole","tomate:4;poivron:1;oignon:1;bouillon:1;huile:10","Émincer l’oignon et couper tomate et poivron en morceaux. / Faire revenir dans l’huile 5 minutes, couvrir d’eau et ajouter le bouillon. / Laisser frémir 20 minutes puis mixer.","🍅","");
  add("entree","Salade de pois chiches au concombre",12,"froid","pois_chiches:250;concombre:1;tomate:2;citron:1;huile:15","Rincer les pois chiches et les égoutter soigneusement. / Couper concombre et tomates en petits dés. / Mélanger avec l’huile et le jus de citron, placer au frais jusqu’au service.","🥗","");
  add("entree","Œufs durs sauce yaourt-moutarde",18,"casserole","oeuf:4;yaourt:1;moutarde:15;herbes:4","Cuire les œufs 9 à 10 minutes puis les refroidir à l’eau froide. / Mélanger le yaourt avec la moutarde et les herbes. / Écaler les œufs, les couper en deux et napper de sauce.","🥚","");
  add("entree","Poireaux vinaigrette",30,"casserole","poireau:3;moutarde:15;vinaigre:15;huile:20","Couper les racines et nettoyer soigneusement les poireaux entre les feuilles. / Les cuire à l’eau frémissante environ 20 minutes jusqu’à tendreté puis égoutter. / Fouetter moutarde, vinaigre et huile, verser au moment du service.","🥬","");
  add("entree","Champignons farcis au fromage",28,"four","champignon:350;fromage:90;ail:7;herbes:4;huile:10","Préchauffer le four à 190 °C puis nettoyer les champignons. / Retirer les pieds, les hacher avec l’ail et les herbes, mélanger au fromage. / Farcir les têtes et cuire 15 à 20 minutes jusqu’à tendreté.","🍄","");
  add("entree","Salade de haricots rouges au maïs",10,"froid","haricots_rouges:230;mais:130;tomate:2;huile:15;citron:1","Rincer haricots rouges et maïs, puis les égoutter. / Couper les tomates en cubes. / Mélanger et assaisonner avec l’huile et le citron juste avant de servir.","🥗","");
  add("entree","Soupe de poireaux et pomme de terre",35,"casserole","poireau:2;pomme_terre:250;bouillon:1;creme:60","Laver les poireaux en séparant les feuilles pour éliminer le sable. / Couper les pommes de terre et faire cuire le tout dans environ 700 ml d’eau avec le bouillon. / Après 25 minutes, mixer et ajouter la crème.","🥣","");
  add("entree","Bâtonnets de légumes sauce fromage blanc",15,"froid","carotte:180;concombre:1;poivron:1;fromage_blanc:160;herbes:4","Éplucher la carotte et laver le concombre et le poivron. / Tailler les légumes en bâtonnets faciles à tremper. / Mélanger fromage blanc et herbes, servir frais avec les crudités.","🥕","");
  add("entree","Tartines de sardines citronnées",10,"froid","pain:4;sardines:130;citron:1;fromage_blanc:70","Écraser les sardines égouttées avec le fromage blanc. / Ajouter quelques gouttes de citron et mélanger à la fourchette. / Tartiner sur du pain grillé et servir immédiatement.","🐟","");
  add("entree","Petite salade de pâtes tomates-mozza",22,"casserole","pates:110;tomate:2;mozzarella:100;huile:15;herbes:4","Cuire les pâtes al dente puis les refroidir rapidement. / Couper les tomates et la mozzarella en dés. / Mélanger avec l’huile et les herbes, puis conserver au frais jusqu’au repas.","🥗","");
  add("entree","Betteraves aux pommes",10,"froid","betterave:250;pomme:1;noix:30;vinaigre:10","Couper les betteraves déjà cuites en cubes et la pomme en petits dés. / Concasser les noix. / Mélanger avec le vinaigre et servir frais.","🍎","");
  add("entree","Mini-feuilletés au chèvre",28,"four","pate_feuilletee:1;chevre:120;miel:20;oeuf:1","Préchauffer le four à 190 °C. / Découper la pâte en six carrés, poser du chèvre au centre et replier les coins. / Badigeonner d’œuf battu et cuire environ 18 minutes, ajouter un peu de miel au service.","🥐","");
  add("entree","Salade de chou rouge aux pommes",15,"froid","chou_rouge:250;pomme:1;huile:15;vinaigre:15;noix:30","Émincer le chou rouge très finement et retirer les parties dures. / Couper la pomme en bâtonnets et concasser les noix. / Mélanger avec huile et vinaigre puis laisser reposer 10 minutes.","🥬","");
  add("plat","Hachis parmentier maison",65,"four","pomme_terre:700;boeuf:320;oignon:1;lait:140;beurre:35;fromage:60","Préchauffer le four à 200 °C. Éplucher les pommes de terre, les couper en cubes réguliers et les cuire environ 20 minutes dans une casserole d’eau légèrement salée. / Pendant leur cuisson, hacher l’oignon et le faire revenir à la poêle 4 minutes. Ajouter le bœuf haché, l’émietter et le cuire complètement en mélangeant. Assaisonner. / Égoutter les pommes de terre cuites, puis les écraser à la fourchette ou au presse-purée. Incorporer peu à peu le lait chaud et le beurre. / Mettre le bœuf dans un plat, le couvrir de purée en une couche régulière et saupoudrer de fromage. / Enfourner 15 à 20 minutes jusqu’à obtenir une croûte dorée. Attendre quelques minutes avant de découper et de servir.","🥘","");
  add("plat","Lasagnes bolognaise faciles",65,"four","lasagnes:160;boeuf:300;coulis:350;oignon:1;fromage:110;lait:300;farine:30;beurre:25","Préchauffer le four à 190 °C. / Faire mijoter le bœuf émietté, l’oignon et le coulis 15 minutes jusqu’à cuisson complète. / Préparer une béchamel en fouettant beurre fondu, farine puis lait jusqu’à épaississement. / Alterner sauce, feuilles de lasagnes et béchamel dans un plat, finir au fromage et cuire 30 à 35 minutes, selon le paquet.","🍝","");
  add("plat","Chili con carne familial",45,"casserole","boeuf:300;haricots_rouges:330;coulis:260;mais:100;oignon:1;paprika:6","Faire dorer l’oignon et le bœuf haché dans une grande casserole. / Ajouter coulis, paprika, haricots égouttés et maïs. / Verser un peu d’eau si besoin et laisser mijoter doucement 20 minutes. / Vérifier que le bœuf est bien cuit avant de servir.","🫘","");
  add("plat","Chili végétarien aux haricots",35,"casserole","haricots_rouges:350;mais:150;coulis:300;poivron:1;oignon:1;paprika:6","Faire revenir l’oignon et le poivron émincés avec un peu d’eau 5 minutes. / Ajouter les haricots rincés, le maïs, le coulis et le paprika. / Laisser mijoter 20 minutes jusqu’à épaississement. / Rectifier l’assaisonnement et servir.","🌶️","");
  add("plat","Tian de légumes provençal",55,"four","courgette:380;aubergine:300;tomate:4;oignon:1;huile:30;herbes:7","Préchauffer le four à 190 °C. / Couper tous les légumes en fines rondelles et les dresser en alternance dans un plat huilé. / Arroser d’huile et parsemer d’herbes. / Cuire environ 40 minutes, couvrir en fin de cuisson si le dessus colore trop.","🍆","");
  add("plat","Ratatouille maison",50,"casserole","courgette:350;aubergine:300;tomate:4;poivron:1;oignon:1;huile:25","Laver les légumes puis les couper en cubes de taille proche. / Faire revenir oignon et poivron dans l’huile 5 minutes. / Ajouter aubergine et courgette, laisser attendrir puis incorporer les tomates. / Cuire à feu doux environ 30 minutes en remuant jusqu’à ce que les légumes soient fondants.","🍆","");
  add("plat","Poivrons farcis au riz et bœuf",60,"four","poivron:2;boeuf:250;riz:100;coulis:180;oignon:1;fromage:50","Préchauffer le four à 190 °C et cuire le riz à moitié selon le paquet. / Faire revenir le bœuf et l’oignon, mélanger avec riz et coulis. / Couper les poivrons en deux, enlever les graines et remplir de farce. / Ajouter le fromage et cuire 30 à 35 minutes, jusqu’à légumes tendres et farce bien cuite.","🫑","");
  add("plat","Tomates farcies au bœuf",55,"four","tomate:4;boeuf:280;riz:110;oignon:1;herbes:5","Préchauffer le four à 190 °C et cuire le riz selon le paquet. / Évider les tomates et hacher leur chair avec l’oignon. / Mélanger au bœuf et aux herbes, remplir les tomates et poser leur chapeau. / Cuire environ 35 minutes en vérifiant la cuisson complète de la viande, servir avec le riz.","🍅","");
  add("plat","Boulettes de bœuf à la tomate",40,"poêle","boeuf:330;oeuf:1;chapelure:40;coulis:300;oignon:1;huile:15","Mélanger bœuf, œuf et chapelure puis former des boulettes de taille égale. / Faire revenir l’oignon avec l’huile, saisir les boulettes de tous les côtés. / Verser le coulis et mijoter à couvert 20 minutes. / Vérifier que les boulettes sont bien cuites à cœur avant de servir.","🍝","");
  add("plat","Steaks sauce moutarde et purée",40,"poêle","steak:2;pomme_terre:550;lait:100;beurre:25;moutarde:25;creme:80","Cuire les pommes de terre épluchées 20 minutes puis les écraser avec lait et beurre. / Saisir les steaks à la poêle selon la cuisson souhaitée et les consignes de sécurité. / Ajouter moutarde et crème dans la poêle, chauffer doucement. / Servir les steaks nappés de sauce avec la purée.","🥩","");
  add("plat","Sauté de porc aux champignons",45,"casserole","porc:350;champignon:260;oignon:1;creme:120;huile:15","Couper le porc en morceaux réguliers et émincer l’oignon. / Faire dorer le porc et l’oignon dans l’huile. / Ajouter les champignons, couvrir et laisser mijoter 25 minutes avec un peu d’eau. / Incorporer la crème et poursuivre jusqu’à cuisson complète du porc.","🍲","");
  add("plat","Rôti de porc aux carottes",70,"four","porc:480;carotte:450;oignon:1;huile:20;herbes:5","Préchauffer le four à 190 °C. / Disposer le porc avec les carottes en tronçons et l’oignon émincé, arroser d’huile. / Ajouter un fond d’eau et cuire environ 50 minutes en arrosant de temps en temps. / Contrôler la cuisson à cœur de la viande avant de trancher.","🍖","");
  add("plat","Poulet basquaise simplifié",45,"casserole","poulet:360;poivron:2;tomate:3;oignon:1;huile:20;herbes:5","Couper les poivrons en lanières et émincer l’oignon. / Faire revenir l’oignon puis dorer le poulet dans l’huile. / Ajouter poivrons, tomates et herbes, couvrir. / Mijoter 25 à 30 minutes jusqu’à cuisson complète du poulet, en remuant doucement.","🍗","");
  add("plat","Poulet miel-moutarde",35,"four","poulet:350;moutarde:30;miel:35;pomme_terre:450;huile:15","Préchauffer le four à 200 °C et couper les pommes de terre en quartiers fins. / Mélanger miel et moutarde, enrober le poulet de cette sauce. / Disposer poulet et pommes de terre sur une plaque, arroser d’huile. / Cuire 25 à 30 minutes en vérifiant que le poulet est bien cuit.","🍗","");
  add("plat","Poulet aux olives et citron",40,"casserole","poulet:360;olives:90;citron:1;oignon:1;huile:15;herbes:4","Faire revenir l’oignon et dorer les morceaux de poulet dans l’huile. / Ajouter les olives, le jus de citron et environ 100 ml d’eau. / Couvrir et cuire doucement 25 minutes en retournant le poulet. / Vérifier la cuisson complète et parsemer d’herbes.","🍋","");
  add("plat","Poulet curry au lait de coco",35,"casserole","poulet:350;lait_coco:220;curry:8;oignon:1;riz:160;huile:15","Cuire le riz dans une casserole d’eau selon le paquet. / Faire revenir l’oignon puis saisir les morceaux de poulet dans l’huile. / Ajouter curry et lait de coco, mijoter 18 à 20 minutes. / Vérifier la cuisson complète du poulet et servir sur le riz.","🍛","");
  add("plat","Wok poulet et brocoli",30,"poêle","poulet:320;brocoli:350;carotte:140;sauce_soja:30;huile:15","Détailler brocoli en petits bouquets et carotte en bâtonnets fins. / Cuire les légumes 5 minutes à la vapeur ou dans un fond d’eau, égoutter. / Faire saisir le poulet en lanières dans l’huile jusqu’à cuisson complète. / Ajouter les légumes et la sauce soja, faire sauter 3 minutes.","🥦","");
  add("plat","Filet de poisson en papillote",35,"four","poisson:340;courgette:220;citron:1;huile:15;herbes:4","Préchauffer le four à 190 °C. / Déposer les filets de poisson sur du papier cuisson avec les courgettes en fines tranches. / Ajouter citron, herbes et huile puis fermer les papillotes sans les serrer. / Cuire 18 à 22 minutes et vérifier que la chair du poisson est opaque et se détache facilement.","🐟","");
  add("plat","Saumon à la moutarde au four",30,"four","saumon:340;moutarde:25;creme:90;citron:1","Préchauffer le four à 190 °C. / Placer les filets dans un plat et mélanger crème, moutarde et jus de citron. / Napper le poisson puis enfourner 15 à 20 minutes selon l’épaisseur. / Vérifier la cuisson du saumon avant de servir.","🐟","");
  add("plat","Saumon teriyaki simplifié",25,"poêle","saumon:330;sauce_soja:30;miel:25;riz:160;huile:10","Faire cuire le riz. / Mélanger la sauce soja et le miel dans un bol. / Saisir le saumon dans l’huile puis verser la sauce et laisser réduire quelques minutes. / Vérifier la cuisson du poisson et servir avec le riz.","🐟","");
  add("plat","Crevettes à l’ail et au citron",22,"poêle","crevettes:320;ail:10;citron:1;riz:150;huile:20","Cuire le riz selon l’emballage. / Faire chauffer l’huile et l’ail haché sans le brûler. / Ajouter les crevettes et les cuire jusqu’à ce qu’elles soient bien chaudes et opaques. / Arroser de citron et servir sur le riz.","🍤","");
  add("plat","Couscous de légumes et pois chiches",40,"casserole","semoule:170;pois_chiches:300;carotte:240;courgette:250;tomate:2;bouillon:1","Couper les carottes et courgettes en morceaux. / Les laisser mijoter 25 minutes avec tomates, bouillon et eau à hauteur. / Ajouter les pois chiches rincés en fin de cuisson. / Préparer la semoule selon le paquet et servir avec les légumes et leur jus.","🥘","");
  add("plat","Semoule au poulet et légumes",35,"casserole","semoule:160;poulet:310;carotte:200;courgette:200;bouillon:1","Couper le poulet en cubes, les carottes et courgettes en morceaux. / Faire revenir le poulet 5 minutes puis ajouter légumes, eau et bouillon. / Couvrir et laisser cuire 20 minutes, jusqu’à cuisson complète du poulet. / Préparer la semoule et la servir avec le mélange.","🍲","");
  add("plat","Poêlée de gnocchis aux champignons",25,"poêle","gnocchi:400;champignon:240;creme:120;parmesan:40;huile:15","Nettoyer et émincer les champignons. / Faire revenir les champignons dans l’huile 7 minutes. / Ajouter les gnocchis et les cuire selon leur emballage, à la poêle ou après passage à l’eau. / Terminer avec crème et parmesan puis servir chaud.","🍄","");
  add("plat","Gnocchis sauce tomate-mozzarella",28,"poêle","gnocchi:400;coulis:300;mozzarella:125;huile:10;herbes:5","Cuire les gnocchis selon leur emballage et les égoutter. / Faire chauffer le coulis avec l’huile et les herbes. / Mélanger aux gnocchis et parsemer de mozzarella coupée. / Couvrir 2 minutes à feu doux jusqu’à ce que le fromage fonde.","🍅","");
  add("plat","Risotto de courgettes au parmesan",35,"casserole","riz:180;courgette:300;oignon:1;bouillon:1;parmesan:50;beurre:20","Émincer l’oignon et couper les courgettes en petits dés. / Faire revenir oignon et riz dans un peu de beurre. / Ajouter progressivement environ 600 ml de bouillon chaud en remuant, incorporer les courgettes à mi-cuisson. / Quand le riz est tendre, ajouter parmesan et beurre restant.","🍚","");
  add("plat","Lentilles à la tomate et carottes",40,"casserole","lentilles:200;carotte:250;coulis:240;oignon:1;bouillon:1","Rincer les lentilles et couper les carottes en petits dés. / Faire revenir l’oignon avec un peu d’eau, ajouter lentilles et carottes. / Verser environ 600 ml d’eau, le bouillon et cuire selon les lentilles. / Ajouter le coulis en fin de cuisson et servir bien chaud.","🫘","");
  add("plat","Dahl de lentilles corail",30,"casserole","lentilles_corail:200;lait_coco:220;coulis:180;curry:7;oignon:1","Rincer les lentilles corail à l’eau claire. / Faire revenir l’oignon puis ajouter curry, lentilles, coulis et lait de coco. / Compléter d’eau à hauteur et laisser mijoter 15 à 20 minutes en remuant. / Servir lorsque les lentilles sont fondantes.","🍛","");
  add("plat","Aubergines gratinées à la tomate",50,"four","aubergine:450;coulis:280;mozzarella:160;huile:20;herbes:5","Préchauffer le four à 200 °C et couper les aubergines en tranches fines. / Badigeonner légèrement d’huile et précuire au four 15 minutes. / Superposer aubergines, coulis et mozzarella dans un plat. / Enfourner encore 20 minutes jusqu’à ce que les aubergines soient bien tendres.","🍆","");
  add("plat","Courgettes farcies au riz",55,"four","courgette:500;riz:140;tomate:2;fromage:100;oignon:1;huile:15","Préchauffer le four à 190 °C et cuire le riz selon son emballage. / Couper les courgettes en deux et creuser légèrement leur cœur. / Mélanger la chair hachée avec riz, tomate et oignon, farcir les demi-courgettes. / Parsemer de fromage puis cuire environ 30 minutes.","🥒","");
  add("plat","Poêlée pommes de terre-chorizo",35,"poêle","pomme_terre:550;chorizo:130;oignon:1;poivron:1;huile:10","Couper les pommes de terre en petits cubes et les précuire 8 minutes à l’eau. / Émincer l’oignon et le poivron, faire revenir à la poêle. / Ajouter pommes de terre et chorizo en rondelles, dorer 12 à 15 minutes. / Vérifier la tendreté des pommes de terre avant de servir.","🥔","");
  add("plat","Pâtes au pesto et tomates cerises",20,"casserole","pates:190;pesto:65;tomates_cerises:200;parmesan:30","Cuire les pâtes dans de l’eau bouillante selon le paquet. / Couper les tomates cerises en deux. / Égoutter en gardant une petite louche d’eau de cuisson. / Mélanger aux pâtes pesto, tomates et parmesan, détendre avec un peu d’eau réservée.","🍝","");
  add("plat","Pâtes aux épinards et ricotta",25,"casserole","pates:190;epinards:220;ricotta:180;ail:6;huile:10","Cuire les pâtes selon l’emballage. / Faire tomber les épinards avec l’ail dans l’huile jusqu’à disparition de leur eau. / Incorporer la ricotta et une louche d’eau de cuisson. / Ajouter les pâtes égouttées et mélanger à feu doux.","🍝","");
  add("plat","Pâtes au saumon et citron",25,"casserole","pates:190;saumon:230;creme:160;citron:1","Cuire les pâtes. / Couper le saumon en morceaux réguliers. / Le cuire doucement dans la crème jusqu’à ce qu’il soit opaque et se détache facilement. / Ajouter un peu de citron et mélanger aux pâtes égouttées.","🐟","");
  add("plat","Nouilles sautées aux crevettes",25,"poêle","nouilles:180;crevettes:250;carotte:150;poivron:1;sauce_soja:30;huile:15","Cuire les nouilles selon l’emballage et les égoutter. / Couper carotte et poivron en fines lanières. / Faire sauter les légumes dans l’huile puis ajouter les crevettes jusqu’à cuisson complète. / Incorporer nouilles et sauce soja, réchauffer 2 minutes.","🍜","");
  add("plat","Riz cantonais maison",30,"poêle","riz_cuit:380;jambon:2;petits_pois:150;oeuf:2;sauce_soja:25;huile:15","Utiliser du riz précédemment cuit, rapidement refroidi et conservé au froid. / Brouiller les œufs dans la poêle puis les réserver. / Faire sauter petits pois et jambon, ajouter le riz et bien le réchauffer. / Réunir œufs et sauce soja et servir immédiatement.","🍚","");
  add("plat","Riz au thon et petits pois",25,"casserole","riz:180;thon:160;petits_pois:150;creme:70;oignon:1","Cuire le riz dans l’eau selon le paquet. / Faire revenir l’oignon, ajouter petits pois et un peu d’eau puis couvrir 8 minutes. / Incorporer le thon égoutté et la crème, chauffer doucement. / Ajouter le riz cuit et mélanger.","🍚","");
  add("plat","Tortilla espagnole",40,"poêle","pomme_terre:500;oeuf:5;oignon:1;huile:25","Couper les pommes de terre en fines lamelles et l’oignon en petits morceaux. / Faire cuire doucement dans une poêle huilée jusqu’à tendreté. / Battre les œufs, y mélanger pommes de terre et oignon. / Reverser dans la poêle, cuire à feu doux puis retourner avec une assiette en prenant garde aux brûlures.","🍳","");
  add("plat","Galettes de courgettes au fromage",25,"poêle","courgette:450;oeuf:2;farine:70;fromage:80;huile:20","Râper les courgettes et bien les presser pour enlever l’eau. / Mélanger avec œufs, farine et fromage râpé. / Déposer de petites portions dans l’huile chaude et les aplatir. / Cuire 4 minutes par face jusqu’à ce que les galettes soient prises et dorées.","🥒","");
  add("plat","Galettes de pommes de terre croustillantes",30,"poêle","pomme_terre:550;oeuf:1;farine:40;oignon:1;huile:25","Râper les pommes de terre et les presser dans un torchon propre. / Mélanger avec œuf, farine et oignon haché. / Former des galettes peu épaisses et cuire dans l’huile à feu modéré. / Retourner après 5 minutes et prolonger jusqu’à cuisson complète des pommes de terre.","🥔","");
  add("plat","Curry de patate douce et pois chiches",35,"casserole","patate_douce:450;pois_chiches:250;lait_coco:220;curry:8;oignon:1","Éplucher la patate douce et couper en petits cubes. / Faire revenir l’oignon puis ajouter curry et patate douce. / Verser le lait de coco et un fond d’eau, couvrir 15 minutes. / Ajouter les pois chiches rincés et cuire jusqu’à ce que la patate douce soit fondante.","🍛","");
  add("plat","Wraps au poulet et crudités",25,"poêle","pain_wrap:4;poulet:300;salade:100;tomate:2;fromage_blanc:120","Couper le poulet en fines lanières et le cuire complètement à la poêle. / Mélanger fromage blanc et quelques herbes si disponibles. / Garnir chaque tortilla de salade, tomate et poulet chaud. / Ajouter la sauce et rouler fermement juste avant de manger.","🌯","");
  add("plat","Wraps végétariens pois chiches",15,"froid","pain_wrap:4;pois_chiches:250;concombre:1;tomate:2;fromage_blanc:120","Rincer les pois chiches puis les écraser grossièrement. / Couper concombre et tomates en dés et les mélanger au fromage blanc. / Répartir le mélange sur les tortillas avec les pois chiches. / Replier les côtés et rouler avant de servir.","🌯","");
  add("plat","Burger de bœuf maison",30,"poêle","pain_burger:2;boeuf:300;tomate:2;salade:70;fromage:80;huile:10","Former deux steaks hachés avec le bœuf et les cuire complètement à cœur. / Couper les pains en deux et les faire dorer dans une poêle sèche. / Poser fromage, steak, tomate et salade sur les pains. / Refermer et servir aussitôt.","🍔","");
  add("plat","Burger végétarien de haricots rouges",35,"poêle","pain_burger:2;haricots_rouges:260;oeuf:1;chapelure:65;salade:60;tomate:1;huile:15","Écraser les haricots rincés et les mélanger à l’œuf et à la chapelure. / Former deux galettes fermes puis les dorer environ 5 minutes par face dans l’huile. / Réchauffer les pains à burger. / Garnir de galette, tomate et salade avant de servir.","🍔","");
  add("plat","Salade composée poulet-avocat",20,"froid","poulet_cuit:240;avocat:1;salade:160;tomate:2;huile:15;citron:1","Vérifier que le poulet est déjà cuit et conservé au froid. / Laver la salade et couper avocat et tomate. / Émincer le poulet en fines tranches. / Répartir tous les éléments et assaisonner avec huile et citron juste avant de servir.","🥗","");
  add("plat","Salade de lentilles au saumon",30,"casserole","lentilles:170;saumon:240;carotte:140;moutarde:15;huile:15","Cuire les lentilles rincées selon leur emballage. / Faire cuire le saumon à la poêle ou à la vapeur jusqu’à chair opaque et détachable. / Râper la carotte et fouetter moutarde et huile. / Mélanger lentilles et carottes, servir avec le saumon émietté.","🥗","");
  add("plat","Quiche aux poireaux et chèvre",50,"four","pate_brisee:1;poireau:3;chevre:130;oeuf:3;creme:180","Préchauffer le four à 190 °C. / Laver puis émincer les poireaux et les faire fondre 12 minutes à la poêle. / Répartir poireaux et chèvre sur la pâte, verser œufs battus et crème. / Enfourner 30 minutes jusqu’à ce que l’appareil soit pris.","🥧","");
  add("plat","Tarte aux épinards et ricotta",50,"four","pate_brisee:1;epinards:350;ricotta:200;oeuf:2;fromage:70","Préchauffer le four à 190 °C et égoutter les épinards après les avoir fait cuire. / Mélanger épinards, ricotta et œufs battus. / Étaler sur la pâte et parsemer de fromage. / Cuire 30 minutes jusqu’à centre ferme et pâte dorée.","🥧","");
  add("plat","Gratin de chou-fleur béchamel",50,"four","chou_fleur:600;lait:350;farine:35;beurre:30;fromage:90","Préchauffer le four à 200 °C et cuire le chou-fleur en bouquets 10 minutes à l’eau. / Faire fondre le beurre, ajouter farine puis lait peu à peu en fouettant. / Mélanger le chou-fleur égoutté à la béchamel, mettre en plat et parsemer de fromage. / Gratiner 20 minutes.","🥦","");
  add("plat","Gratin de brocoli au jambon",45,"four","brocoli:500;jambon:3;creme:180;fromage:100","Préchauffer le four à 200 °C et cuire le brocoli en bouquets 8 minutes à l’eau. / Égoutter soigneusement puis mélanger avec le jambon coupé en lanières. / Verser la crème et ajouter le fromage. / Gratiner 20 minutes jusqu’à coloration.","🥦","");
  add("plat","Soupe-repas de légumes et lentilles",40,"casserole","lentilles_corail:160;carotte:200;pomme_terre:220;poireau:1;bouillon:1","Rincer les lentilles et laver soigneusement les légumes. / Couper tous les légumes en petits dés. / Faire cuire avec bouillon et environ 800 ml d’eau pendant 25 minutes. / Servir en soupe épaisse, en mixant une petite partie si souhaité.","🥣","");
  add("plat","Velouté potiron et pois chiches",35,"casserole","potiron:550;pois_chiches:200;oignon:1;creme:100;bouillon:1","Couper le potiron en cubes et émincer l’oignon. / Cuire avec le bouillon et environ 600 ml d’eau durant 20 minutes. / Ajouter les pois chiches rincés, cuire encore 5 minutes. / Mixer avec la crème jusqu’à texture veloutée.","🎃","");
  add("plat","Omelette aux herbes et chèvre",15,"poêle","oeuf:4;chevre:90;herbes:7;beurre:15","Battre les œufs avec les herbes finement hachées. / Faire fondre le beurre dans une poêle à feu doux. / Verser les œufs, déposer le chèvre émietté. / Replier lorsque la surface est juste prise et servir immédiatement.","🍳","");
  add("plat","Frittata aux légumes",40,"four","oeuf:5;courgette:250;tomate:2;fromage:80;huile:15","Préchauffer le four à 180 °C et huiler un plat. / Couper courgette et tomate en petits morceaux et les répartir au fond. / Battre les œufs avec le fromage, verser sur les légumes. / Cuire 25 minutes jusqu’à ce que la frittata soit prise au centre.","🍳","");
  add("plat","Shakshuka aux œufs et tomates",30,"poêle","oeuf:4;tomate:4;poivron:1;oignon:1;coulis:130;huile:15","Émincer oignon et poivron et les faire revenir dans l’huile. / Ajouter tomates coupées et coulis, mijoter 12 minutes. / Creuser quatre petits puits et casser les œufs dedans. / Couvrir et cuire jusqu’à ce que les blancs soient pris.","🍳","");
  add("plat","Blanquette de poulet simplifiée",50,"casserole","poulet:380;carotte:220;champignon:200;creme:140;farine:25;bouillon:1","Couper le poulet en morceaux et les carottes en rondelles. / Faire mijoter poulet, carottes et bouillon dans environ 450 ml d’eau durant 25 minutes. / Ajouter les champignons puis délayer la farine avec un peu de bouillon froid et verser dans la casserole. / Incorporer la crème, laisser épaissir et vérifier la cuisson complète du poulet.","🍲","");
  add("plat","Bœuf aux carottes rapide",60,"casserole","boeuf:360;carotte:350;oignon:1;bouillon:1;huile:15","Couper le bœuf en petits morceaux adaptés à une cuisson en sauce et émincer l’oignon. / Faire dorer la viande et l’oignon dans l’huile. / Ajouter les carottes, le bouillon et de l’eau à hauteur. / Couvrir et laisser mijoter jusqu’à viande bien tendre, prolonger si nécessaire.","🥩","");
  add("plat","Poisson pané maison",30,"poêle","poisson:320;oeuf:1;farine:45;chapelure:85;huile:30","Sécher les filets et préparer trois assiettes : farine, œuf battu, chapelure. / Enrober chaque filet de farine puis d’œuf et enfin de chapelure. / Faire cuire à feu moyen dans l’huile, en retournant délicatement. / Vérifier que la chair est opaque et bien cuite au centre.","🐟","");
  add("plat","Galettes de thon et pomme de terre",35,"poêle","thon:190;pomme_terre:400;oeuf:1;chapelure:65;huile:20","Cuire les pommes de terre à l’eau, les égoutter et les écraser. / Mélanger à la purée le thon égoutté, l’œuf et la chapelure. / Former de petites galettes et les saisir dans l’huile 4 minutes par face. / Servir dès qu’elles sont bien dorées et chaudes à cœur.","🐟","");
  add("plat","Raclette aux légumes",35,"raclette","pomme_terre:600;fromage:340;champignon:180;courgette:200;cornichon:80","Cuire les pommes de terre et couper les légumes en tranches fines. / Précuire les courgettes si nécessaire pour qu’elles soient tendres. / Faire fondre le fromage dans les coupelles selon la notice de l’appareil. / Servir avec pommes de terre, légumes et cornichons.","🧀","");
  add("plat","Crêpes salées jambon-champignons",35,"crêpière","farine:145;lait:290;oeuf:3;jambon:2;champignon:180;fromage:70","Mélanger farine, lait et deux œufs en pâte lisse. / Cuire quatre crêpes dans la crêpière préchauffée. / Faire revenir les champignons jusqu’à ce qu’ils aient rendu leur eau, ajouter le jambon. / Garnir les crêpes de champignons, jambon et fromage puis les réchauffer repliées.","🥞","");
  add("plat","Gaufres salées courgette-fromage",30,"gaufrier","courgette:240;farine:140;lait:160;oeuf:2;fromage:90;levure:5","Râper la courgette et presser fortement pour enlever l’eau. / Mélanger farine, levure, lait et œufs puis ajouter courgette et fromage. / Préchauffer le gaufrier, déposer une portion de pâte. / Cuire jusqu’à dorure, en suivant les consignes du fabricant.","🧇","");
  add("plat","Poêlée de haricots verts et lardons",25,"poêle","haricots_verts:450;lardons:150;pomme_terre:250;oignon:1","Cuire les pommes de terre en dés et les haricots verts séparément jusqu’à tendreté. / Faire dorer les lardons et l’oignon émincé dans une grande poêle. / Ajouter les légumes égouttés, faire sauter 5 minutes. / Servir très chaud.","🥘","");
  add("plat","Salade de riz façon méditerranéenne",25,"casserole","riz:180;tomate:2;concombre:1;olives:70;feta:110;huile:15","Cuire le riz puis le refroidir rapidement au réfrigérateur. / Couper concombre, tomates et feta en dés. / Égoutter les olives si nécessaire. / Mélanger avec huile et riz froid, conserver au frais jusqu’au service.","🥗","");
  add("plat","Salade de pâtes au pesto et poulet",30,"casserole","pates:180;poulet:300;pesto:65;tomates_cerises:150","Cuire les pâtes puis les refroidir rapidement. / Cuire complètement le poulet en petits morceaux à la poêle. / Mélanger avec le pesto et les tomates cerises coupées. / Réserver au froid et servir le jour même.","🥗","");
  add("plat","Tajine doux de légumes",45,"casserole","carotte:240;courgette:250;pois_chiches:260;tomate:2;semoule:160;cannelle:2","Couper carottes et courgettes en morceaux, les tomates en cubes. / Faire mijoter les légumes avec un fond d’eau et une petite pincée de cannelle durant 25 minutes. / Ajouter les pois chiches rincés et cuire encore 5 minutes. / Préparer la semoule selon le paquet et servir avec les légumes.","🥘","");
  add("plat","Gratin de patate douce et chèvre",55,"four","patate_douce:650;chevre:160;creme:160;herbes:5","Préchauffer le four à 190 °C et éplucher les patates douces. / Couper en rondelles fines et les répartir dans un plat à gratin. / Verser la crème et ajouter chèvre émietté et herbes. / Cuire 35 à 40 minutes jusqu’à tendreté des patates douces.","🍠","");
  add("plat","Purée de patate douce et saumon",35,"casserole","patate_douce:600;saumon:330;beurre:25;lait:80;citron:1","Éplucher et couper les patates douces en cubes, cuire à l’eau jusqu’à tendreté. / Écraser avec le lait et le beurre. / Cuire les filets de saumon à la vapeur ou à la poêle jusqu’à chair opaque. / Servir avec quelques gouttes de citron.","🐟","");
  add("plat","Curry de chou-fleur et pois chiches",35,"casserole","chou_fleur:500;pois_chiches:250;lait_coco:250;curry:9;oignon:1","Détailler le chou-fleur en petits bouquets, émincer l’oignon. / Faire revenir oignon et curry avec un peu d’eau. / Ajouter chou-fleur, lait de coco et un fond d’eau, mijoter 18 minutes. / Incorporer les pois chiches et prolonger jusqu’à chou-fleur tendre.","🍛","");
  add("dessert","Clafoutis aux cerises",50,"four","cerise:350;farine:90;lait:220;oeuf:3;sucre:75;beurre:15","Préchauffer le four à 180 °C et beurrer un plat. / Laver et dénoyauter les cerises avec soin. / Fouetter œufs et sucre, ajouter farine et lait progressivement puis verser sur les fruits. / Cuire 35 minutes jusqu’à centre pris et surface dorée.","🍒","");
  add("dessert","Compote pommes-poires maison",30,"casserole","pomme:3;poire:3;cannelle:2;sucre:20","Éplucher les fruits, retirer les pépins et les couper en dés. / Les placer dans une casserole avec un petit fond d’eau et la cannelle. / Couvrir et cuire 20 minutes en remuant, puis écraser selon la texture souhaitée. / Sucrer seulement si nécessaire et laisser tiédir.","🍐","");
  add("dessert","Gâteau au chocolat moelleux",40,"four","chocolat:150;beurre:95;farine:100;oeuf:3;sucre:110;levure:5","Préchauffer le four à 180 °C et beurrer un petit moule. / Faire fondre chocolat et beurre à feu doux puis laisser tiédir. / Fouetter œufs et sucre, incorporer chocolat puis farine et levure. / Cuire 25 à 30 minutes et vérifier la cuisson avec la pointe d’un couteau.","🍫","");
  add("dessert","Crème dessert vanille maison",20,"casserole","lait:450;sucre:55;farine:35;vanille:3","Délayer la farine dans un peu de lait froid pour éviter les grumeaux. / Chauffer le reste du lait avec vanille et sucre. / Verser le mélange farine-lait, fouetter sur feu doux jusqu’à épaississement. / Répartir dans des ramequins et laisser refroidir au réfrigérateur.","🍮","");
  add("dessert","Crème chocolat à la casserole",20,"casserole","lait:450;cacao:28;sucre:60;farine:35","Mélanger cacao, sucre et farine dans une casserole à froid. / Ajouter le lait peu à peu en fouettant. / Faire chauffer à feu doux sans cesser de remuer jusqu’à épaississement. / Verser dans des pots, laisser refroidir et réfrigérer.","🍫","");
  add("dessert","Poires rôties au miel",35,"four","poire:3;miel:45;beurre:25;cannelle:2","Préchauffer le four à 190 °C et couper les poires en deux. / Retirer les pépins et déposer les demi-poires dans un plat beurré. / Arroser de miel et ajouter une pincée de cannelle. / Cuire 20 à 25 minutes jusqu’à fruits tendres.","🍐","");
  add("dessert","Pommes au four à la cannelle",35,"four","pomme:4;miel:45;beurre:25;cannelle:3","Préchauffer le four à 180 °C. / Retirer le cœur des pommes sans les percer jusqu’au fond. / Garnir les cavités de miel, beurre et cannelle. / Cuire environ 25 minutes jusqu’à pommes tendres.","🍎","");
  add("dessert","Crumble poire-chocolat",40,"four","poire:3;chocolat:90;farine:105;beurre:70;sucre:70","Préchauffer le four à 180 °C et couper les poires en cubes. / Les répartir dans un plat avec le chocolat en morceaux. / Sabler farine, beurre froid et sucre du bout des doigts, couvrir les fruits. / Cuire 25 minutes jusqu’à crumble doré.","🍫","");
  add("dessert","Salade de fraises à la menthe",10,"froid","fraise:300;menthe:6;citron:1;sucre:20","Laver les fraises rapidement puis enlever les queues. / Couper les fraises en deux et ciseler la menthe lavée. / Mélanger avec une cuillère de jus de citron et un peu de sucre. / Laisser reposer 5 minutes avant de servir.","🍓","");
  add("dessert","Verrines mangue-fromage blanc",10,"froid","mangue:1;fromage_blanc:320;miel:25;biscuit:40","Éplucher la mangue et la couper en petits cubes. / Répartir le fromage blanc dans deux verrines. / Ajouter mangue, miel puis biscuits émiettés juste avant le service. / Servir bien frais.","🥭","");
  add("dessert","Flan aux œufs vanillé",55,"four","lait:400;oeuf:3;sucre:80;vanille:3","Préchauffer le four à 160 °C et préparer un bain-marie dans un plat profond. / Chauffer le lait avec vanille et fouetter les œufs avec le sucre. / Verser le lait tiède progressivement sur les œufs, répartir dans des ramequins. / Cuire au bain-marie 35 à 40 minutes jusqu’à prise, puis refroidir au réfrigérateur.","🍮","");
  add("dessert","Tarte aux poires et amandes",50,"four","pate_brisee:1;poire:3;amandes:110;beurre:80;sucre:80;oeuf:2","Préchauffer le four à 180 °C et étaler la pâte dans un moule. / Mélanger beurre mou, sucre, œufs et amandes en poudre. / Répartir cette crème sur la pâte puis disposer les poires épluchées en lamelles. / Cuire environ 35 minutes jusqu’à dorure et centre pris.","🥧","");
  add("dessert","Cookies avoine et raisins secs",25,"four","flocons:120;farine:80;raisins_secs:80;beurre:75;sucre:65;oeuf:1","Préchauffer le four à 180 °C et préparer une plaque. / Mélanger beurre mou et sucre, ajouter œuf, farine, flocons et raisins. / Former de petits tas espacés sur une feuille de cuisson. / Cuire 10 à 12 minutes et laisser refroidir sur la plaque.","🍪","");
  add("dessert","Moelleux citron maison",40,"four","farine:135;sucre:95;oeuf:2;beurre:90;citron:1;levure:6","Préchauffer le four à 180 °C et beurrer un moule. / Fouetter œufs et sucre, ajouter beurre fondu et zeste fin du citron lavé. / Incorporer farine et levure puis un peu de jus de citron. / Cuire environ 25 minutes, vérifier au couteau et laisser refroidir.","🍋","");
  add("dessert","Verrine chocolat-banane et yaourt",10,"froid","yaourt:2;banane:2;chocolat:60;biscuit:45","Couper les bananes en rondelles et écraser les biscuits. / Faire fondre doucement le chocolat puis le laisser tiédir. / Alterner yaourt, banane et biscuit dans deux verres. / Ajouter un filet de chocolat et servir frais.","🍌","");
  add("dessert","Riz au lait à la cannelle",45,"casserole","riz:110;lait:500;sucre:50;cannelle:3","Rincer brièvement le riz si indiqué sur le paquet. / Verser riz et lait dans une casserole à fond épais. / Cuire 35 à 40 minutes à feu doux en remuant régulièrement. / Incorporer sucre et cannelle en fin de cuisson puis laisser tiédir.","🥣","");
  add("dessert","Gaufres chocolat et poire",30,"gaufrier","farine:160;lait:190;oeuf:2;levure:6;beurre:30;poire:2;chocolat:85","Préparer une pâte lisse avec farine, levure, œufs, lait et beurre fondu. / Cuire dans le gaufrier préchauffé selon sa notice. / Faire fondre le chocolat à feu doux et couper les poires en fines lamelles. / Servir les gaufres avec poire et chocolat.","🧇","");
  add("dessert","Coupes de fruits rouges et fromage blanc",8,"froid","fromage_blanc:300;fraise:140;framboise:140;miel:25","Rincer délicatement les fraises et retirer leur queue. / Répartir le fromage blanc dans deux bols. / Ajouter les fruits rouges et arroser d’un peu de miel. / Déguster sans attendre.","🍓","");
  add("petit","Toast œuf dur et avocat",16,"casserole","pain:4;oeuf:2;avocat:1;citron:1","Plonger les œufs dans l’eau bouillante 9 minutes puis les refroidir. / Écaler les œufs et les couper en rondelles. / Écraser l’avocat avec un peu de citron. / Tartiner le pain grillé et ajouter les œufs.","🥑","");
  add("petit","Muesli aux fruits rouges",6,"froid","cereales:105;fraise:110;framboise:90;yaourt:2","Laver les fruits rouges délicatement. / Répartir les yaourts dans des bols, verser les céréales. / Disposer les fruits sans trop les écraser, déguster rapidement.","🥣","");
  add("petit","Crêpes aux poires tièdes",28,"crêpière","farine:145;lait:270;oeuf:2;poire:2;beurre:25;sucre:20","Fouetter farine, lait et œufs en pâte lisse. / Cuire les crêpes dans la crêpière selon sa notice. / Faire revenir les poires en lamelles dans le beurre avec un peu de sucre. / Garnir les crêpes et servir tiède.","🥞","");
  add("petit","Tartines fromage blanc et miel",6,"froid","pain:4;fromage_blanc:140;miel:30;amandes:30","Griller légèrement le pain puis le laisser tiédir. / Étaler du fromage blanc sur les tranches. / Répartir miel et amandes concassées juste avant de servir.","🍯","");
  add("petit","Œufs brouillés aux tomates",13,"poêle","oeuf:4;tomate:2;beurre:15;herbes:4","Couper les tomates en petits cubes, enlever le jus abondant. / Les faire revenir 2 minutes dans le beurre. / Ajouter les œufs battus, cuire à feu doux en remuant. / Parsemer d’herbes au moment de servir.","🍳","");
  add("entree","Concombres farcis au fromage frais",12,"froid","concombre:1;fromage_blanc:150;herbes:6;citron:1","Couper le concombre dans la longueur puis retirer les graines avec une cuillère. / Mélanger le fromage blanc épais, les herbes hachées et quelques gouttes de citron. / Garnir les demi-concombres et découper en tronçons. / Conserver au frais jusqu’au service.","🥒","");
  add("entree","Salade de melon et jambon",10,"froid","melon:1;jambon:3;salade:90","Couper le melon en deux, retirer les pépins puis la peau. / Le tailler en cubes ou en tranches et répartir la salade lavée sur un plat. / Ajouter les morceaux de jambon et servir très frais.","🍈","");
  add("entree","Verrines betterave et fromage blanc",15,"froid","betterave:280;fromage_blanc:180;noix:35;citron:1","Couper les betteraves cuites en petits dés. / Mélanger le fromage blanc avec quelques gouttes de citron. / Alterner dans les verrines betterave et fromage blanc. / Parsemer de noix concassées et réserver au frais.","🥗","");
  add("entree","Salade d’orange et fenouil",12,"froid","fenouil:1;orange:2;huile:15;citron:1","Laver le fenouil et l’émincer très finement. / Peler les oranges à vif et recueillir le jus. / Mélanger huile, jus d’orange et un peu de citron. / Répartir le fenouil et les oranges puis assaisonner.","🍊","");
  add("entree","Velouté de brocoli au parmesan",30,"casserole","brocoli:500;pomme_terre:180;parmesan:45;bouillon:1","Séparer le brocoli en bouquets et couper la pomme de terre épluchée. / Faire cuire avec le bouillon et de l’eau à hauteur 20 minutes. / Mixer finement puis incorporer le parmesan. / Ajuster l’épaisseur avec un peu d’eau chaude.","🥦","");
  add("plat","Poulet à la tomate et olives",40,"casserole","poulet:350;olives:100;coulis:280;oignon:1;huile:15","Faire revenir l’oignon haché dans l’huile puis ajouter les morceaux de poulet. / Faire dorer toutes les faces, incorporer le coulis et un fond d’eau. / Couvrir et cuire 20 minutes. / Ajouter les olives, poursuivre 5 minutes et vérifier la cuisson complète du poulet.","🍗","");
  add("plat","Penne à la crème de champignons",25,"casserole","pates:190;champignon:300;creme:160;ail:6;huile:15","Cuire les pâtes selon l’emballage et réserver une petite tasse d’eau de cuisson. / Émincer les champignons et les saisir dans l’huile jusqu’à disparition de l’eau. / Ajouter l’ail puis la crème, laisser réduire 3 minutes. / Mélanger aux pâtes et détendre si nécessaire.","🍝","");
  add("plat","Purée de pommes de terre et œufs mollets",35,"casserole","pomme_terre:600;oeuf:4;lait:110;beurre:25","Éplucher les pommes de terre, les cuire à l’eau pendant 20 minutes puis égoutter. / Les écraser avec le lait chaud et le beurre. / Cuire les œufs 6 minutes dans l’eau frémissante, les refroidir puis les écaler délicatement. / Servir immédiatement sur la purée.","🥔","");
  add("plat","Tarte courgette-tomate",45,"four","pate_brisee:1;courgette:350;tomate:3;oeuf:2;creme:130;fromage:70","Préchauffer le four à 190 °C. / Couper les courgettes et tomates en rondelles, faire revenir les courgettes quelques minutes. / Répartir sur la pâte puis verser le mélange œufs-crème. / Ajouter le fromage et cuire 30 minutes jusqu’à centre pris.","🥧","");
  add("plat","Riz crémeux au potiron",40,"casserole","riz:180;potiron:350;creme:100;oignon:1;bouillon:1;fromage:60","Couper la courge en petits dés et émincer l’oignon. / Faire revenir oignon et riz 2 minutes puis ajouter la courge. / Verser progressivement environ 600 ml de bouillon chaud et cuire en remuant. / Quand le riz est tendre, ajouter crème et fromage.","🎃","");
  add("plat","Steaks et poêlée de haricots verts",25,"poêle","steak:2;haricots_verts:450;ail:7;beurre:20","Faire cuire les haricots verts à l’eau jusqu’à tendreté puis les égoutter. / Les faire sauter avec l’ail dans la moitié du beurre. / Saisir les steaks séparément dans le beurre restant selon la cuisson souhaitée, en respectant les consignes de sécurité. / Servir bien chaud.","🥩","");
  add("plat","Papillotes de saumon aux poireaux",35,"four","saumon:350;poireau:2;citron:1;creme:70","Préchauffer le four à 190 °C. / Laver les poireaux, les couper finement et les précuire 7 minutes dans un fond d’eau. / Répartir les poireaux sur deux feuilles de cuisson, déposer le saumon, citron et crème. / Fermer et cuire 18 à 22 minutes, jusqu’à chair opaque.","🐟","");
  add("plat","Boulettes de pois chiches à la poêle",30,"poêle","pois_chiches:320;oeuf:1;chapelure:75;herbes:7;huile:20","Rincer et égoutter soigneusement les pois chiches puis les écraser. / Incorporer œuf, chapelure et herbes, mélanger jusqu’à pâte façonnable. / Former de petites boulettes aplaties et les dorer à la poêle 4 minutes par côté. / Servir chaudes et bien prises à cœur.","🫘","");
  add("plat","Salade de quinoa aux légumes croquants",28,"casserole","quinoa:180;concombre:1;tomate:2;carotte:150;citron:1;huile:20","Rincer le quinoa et le cuire suivant l’emballage, puis le refroidir rapidement. / Couper concombre et tomates en cubes, râper la carotte. / Fouetter huile et jus de citron. / Mélanger le tout et garder au frais jusqu’au service.","🥗","");
  add("plat","Gratin de gnocchis tomate et fromage",35,"four","gnocchi:420;coulis:300;fromage:140;herbes:6","Préchauffer le four à 200 °C et vérifier si les gnocchis nécessitent une précuisson selon le paquet. / Mélanger gnocchis et coulis dans un plat. / Parsemer de fromage râpé et d’herbes. / Enfourner 20 minutes jusqu’à garniture chaude et fromage doré.","🧀","");
  add("plat","Aubergines à la poêle et œufs",30,"poêle","aubergine:400;oeuf:4;coulis:190;huile:20;ail:6","Couper les aubergines en petits cubes réguliers. / Les faire revenir dans l’huile 12 minutes avec l’ail, en ajoutant un fond d’eau si nécessaire. / Verser le coulis et laisser mijoter 5 minutes. / Casser les œufs dessus, couvrir jusqu’à ce que les blancs soient pris.","🍆","");
  add("plat","Filet de poisson sauce citron",30,"poêle","poisson:340;citron:1;creme:110;riz:160;huile:15","Cuire le riz selon le paquet. / Chauffer l’huile et saisir les filets de poisson délicatement. / Ajouter la crème et un peu de citron puis laisser mijoter à feu doux. / Vérifier que le poisson est bien cuit et servir avec le riz.","🐟","");
  add("plat","Bœuf haché et légumes à la mexicaine",35,"poêle","boeuf:320;haricots_rouges:200;poivron:1;mais:140;coulis:150;paprika:5","Faire revenir le bœuf émietté jusqu’à cuisson complète. / Ajouter le poivron en petits cubes et cuire 8 minutes. / Incorporer haricots rincés, maïs, coulis et paprika. / Laisser mijoter 10 minutes et servir chaud.","🌶️","");
  add("plat","Poêlée de courgettes au chorizo",25,"poêle","courgette:500;chorizo:130;oignon:1;riz:140","Cuire le riz selon le paquet. / Couper les courgettes en dés et l’oignon en fines tranches. / Faire revenir oignon et chorizo puis ajouter les courgettes. / Couvrir 10 minutes, vérifier tendreté et servir sur le riz.","🥒","");
  add("plat","Tortillas au thon et tomate",15,"froid","pain_wrap:4;thon:200;tomate:2;salade:120;fromage_blanc:100","Égoutter le thon et couper les tomates en dés. / Mélanger le thon au fromage blanc pour obtenir une garniture. / Déposer salade et tomates sur les tortillas, ajouter le thon. / Rouler fermement et servir frais.","🌯","");
  add("plat","Soupe de chou-fleur et pommes de terre",35,"casserole","chou_fleur:500;pomme_terre:300;poireau:1;bouillon:1;creme:90","Laver chou-fleur et poireau, éplucher les pommes de terre. / Couper en petits morceaux et cuire 25 minutes dans le bouillon avec de l’eau à hauteur. / Mixer jusqu’à texture homogène. / Ajouter la crème et réchauffer doucement sans bouillir.","🥣","");
  add("plat","Omelette courgette et mozzarella",20,"poêle","oeuf:4;courgette:260;mozzarella:120;huile:15","Râper la courgette puis retirer son eau en la pressant. / Faire revenir dans l’huile 5 minutes. / Verser les œufs battus et ajouter la mozzarella en petits morceaux. / Couvrir et cuire doucement jusqu’à ce que l’omelette soit prise.","🍳","");
  add("plat","Riz aux petits pois et parmesan",28,"casserole","riz:190;petits_pois:200;bouillon:1;parmesan:65;beurre:20","Rincer le riz si indiqué sur le paquet. / Le faire cuire dans environ 500 ml de bouillon chaud, en surveillant l’absorption. / Ajouter les petits pois en fin de cuisson pour les réchauffer et les attendrir. / Incorporer le beurre et le parmesan avant de servir.","🍚","");
  add("dessert","Verrines poire et chocolat croquant",12,"froid","poire:2;fromage_blanc:250;chocolat:65;biscuit:40","Couper les poires en petits dés et écraser les biscuits. / Hacher le chocolat en fins éclats. / Superposer fromage blanc, fruits, biscuits et chocolat. / Garder au frais et ajouter les biscuits au dernier moment pour le croquant.","🍐","");
  add("dessert","Gâteau moelleux pomme-cannelle",45,"four","pomme:3;farine:145;oeuf:2;sucre:90;beurre:75;cannelle:3;levure:6","Préchauffer le four à 180 °C et beurrer un moule. / Fouetter les œufs et le sucre, incorporer beurre fondu, farine, levure et cannelle. / Ajouter les pommes pelées et coupées en dés. / Cuire 30 minutes environ et vérifier la cuisson à la pointe d’un couteau.","🍎","");
  add("dessert","Petits flans chocolat au four",50,"four","lait:370;oeuf:3;chocolat:100;sucre:45","Préchauffer le four à 160 °C et placer les ramequins dans un plat pour bain-marie. / Faire fondre le chocolat dans le lait chaud et laisser tiédir. / Fouetter œufs et sucre puis ajouter le lait chocolaté progressivement. / Verser en ramequins et cuire 35 minutes au bain-marie jusqu’à prise, puis réfrigérer.","🍫","");
  // V0.3.1 — recettes originales, détaillées et compatibles avec le stock.
  add("plat","Blanquette de veau traditionnelle",120,"casserole","veau:420;carotte:260;champignon:180;oignon:1;bouillon:1;beurre:35;farine:30;creme:130;citron:1;riz:150","Éplucher les carottes et les couper en rondelles. Émincer l’oignon et nettoyer les champignons avant de les couper en quartiers. / Placer les morceaux de veau dans une grande casserole. Ajouter les carottes, l’oignon, le bouillon et environ 800 ml d’eau, pour couvrir presque à hauteur. Porter doucement à frémissement. / Écumer si nécessaire, couvrir et laisser mijoter à feu très doux 75 à 90 minutes, jusqu’à ce que le veau soit bien cuit et tendre. Ajouter les champignons pour les 15 dernières minutes. / Prélever environ 300 ml de bouillon de cuisson et le filtrer si besoin. Dans une autre casserole, faire fondre le beurre, ajouter la farine et remuer 2 minutes sans laisser colorer. / Verser progressivement le bouillon prélevé sur le mélange beurre-farine en fouettant, puis faire épaissir à feu doux 4 à 5 minutes. Incorporer la crème et une cuillère à soupe de jus de citron. / Remettre le veau et les légumes dans la sauce. Réchauffer quelques minutes sans forte ébullition, goûter et rectifier sel et poivre. / Pendant la fin de la cuisson, préparer le riz selon les indications de son emballage. Servir le veau bien chaud avec le riz et la sauce.","🍲","Prévoir une cuisson lente : si la viande est encore ferme, poursuivre le mijotage jusqu’à tendreté. Préparation sans vin.");
  add("plat","Bœuf bourguignon familial",190,"casserole","boeuf_mijoter:450;vin_rouge:350;carotte:260;oignon:2;lardons:100;champignon:180;farine:20;huile:20;bouillon:1;herbes:6","Découper le bœuf à mijoter en cubes de 3 à 4 cm. Éplucher les carottes et les couper en rondelles. Émincer les oignons, nettoyer les champignons. / Dans une cocotte, chauffer l’huile puis faire dorer les morceaux de bœuf sur plusieurs faces, en plusieurs fois si nécessaire. Réserver sur une assiette. / Faire revenir les lardons et les oignons environ 5 minutes. Ajouter les carottes et la farine, mélanger pendant une minute. / Remettre le bœuf, verser le vin rouge et environ 250 ml d’eau avec le bouillon. Ajouter les herbes, porter à frémissement et couvrir. / Laisser mijoter à feu très doux pendant 2 h 30 à 3 h en remuant de temps en temps, jusqu’à ce que la viande soit très tendre. Ajouter un peu d’eau chaude si la sauce réduit trop. / Faire cuire séparément les champignons dans une poêle chaude puis les incorporer à la cocotte 20 minutes avant la fin. / Retirer les herbes si nécessaire, goûter, assaisonner et servir très chaud avec une purée ou des pommes de terre. Ne pas remplacer une cuisson longue par une cuisson rapide : la viande doit devenir tendre.","🥘","Contient du vin et du porc. Pour une version sans alcool, remplacer le vin par du bouillon et ajuster l’assaisonnement ; le résultat sera différent de la recette classique.");
  add("plat","Bœuf-carottes mijoté",115,"casserole","boeuf_mijoter:420;carotte:450;oignon:1;bouillon:1;huile:18;herbes:5;pomme_terre:400","Éplucher les carottes et les pommes de terre, puis les couper en morceaux réguliers. Hacher l’oignon. / Chauffer l’huile dans une cocotte, saisir les morceaux de bœuf à mijoter pour les colorer de tous les côtés. / Ajouter l’oignon et le laisser revenir 3 minutes. Verser environ 600 ml d’eau avec le bouillon et les herbes, puis couvrir. / Faire mijoter à feu doux 70 minutes. Ajouter les carottes et poursuivre 25 minutes, puis les pommes de terre pour les 20 dernières minutes, jusqu’à cuisson complète et tendreté de la viande. / Vérifier le niveau de liquide pendant la cuisson, assaisonner et servir bien chaud, avec un peu de jus de cuisson.","🥕","La cuisson totale dépend du morceau : prolonger si le bœuf n’est pas encore tendre.");
  add("dessert","Gâteau nature facile",45,"four","farine:160;sucre:110;oeuf:2;lait:90;beurre:80;levure:8;vanille:3","Préchauffer le four à 180 °C. Beurrer et fariner un moule de 18 cm. / Faire fondre le beurre à feu doux puis le laisser tiédir. / Dans un saladier, fouetter les œufs avec le sucre jusqu’à ce que le mélange mousse légèrement. / Ajouter le beurre, le lait et la vanille, puis incorporer farine et levure sans trop travailler la pâte. / Verser dans le moule et cuire 28 à 33 minutes. Vérifier la cuisson en plantant une pointe de couteau au centre : elle doit ressortir sans pâte crue. / Laisser reposer 10 minutes avant de démouler puis refroidir sur une grille.","🍰","Moule conseillé : 18 cm ; pour un gâteau plus gros, augmenter les quantités et la durée de cuisson.");
  add("dessert","Quatre-quarts facile",55,"four","oeuf:2;sucre:115;farine:115;beurre:115;levure:5;vanille:3","Préchauffer le four à 170 °C. Beurrer et fariner un moule à cake de petite taille. / Faire fondre le beurre et le laisser tiédir. / Fouetter les œufs et le sucre jusqu’à ce que le mélange blanchisse. / Ajouter le beurre fondu, puis la farine, la levure et la vanille. Mélanger juste assez pour obtenir une pâte homogène. / Verser dans le moule et enfourner pour environ 35 à 40 minutes. Si le dessus dore trop vite, le protéger avec une feuille de cuisson. / Vérifier avec la pointe d’un couteau, laisser tiédir 10 minutes et démouler.","🍰","Version simplifiée : le quatre-quarts traditionnel utilise le même poids d’œufs, de beurre, de sucre et de farine.");
  add("dessert","Gâteau au yaourt et aux pommes",45,"four","yaourt:1;farine:155;sucre:100;oeuf:2;huile:55;levure:8;pomme:2","Préchauffer le four à 180 °C et huiler légèrement un moule de 18 à 20 cm. / Peler les pommes, retirer les pépins et couper une pomme en dés et l’autre en lamelles. / Mélanger le yaourt, les œufs et le sucre dans un saladier. Incorporer l’huile, la farine et la levure. / Ajouter les dés de pomme à la pâte puis verser dans le moule. Déposer les lamelles sur le dessus. / Cuire environ 30 à 35 minutes jusqu’à ce que le centre soit pris et qu’une lame ressorte sèche. / Laisser tiédir avant de servir.","🍎","Une seule pomme suffit si tu préfères un gâteau moins fruité.");
  add("dessert","Cake à la banane",55,"four","banane:2;farine:155;oeuf:2;sucre:70;beurre:65;levure:8;vanille:3","Préchauffer le four à 175 °C et beurrer un petit moule à cake. / Peler les bananes très mûres et les écraser à la fourchette dans un saladier. / Fouetter les œufs et le sucre, incorporer le beurre fondu tiède puis la purée de bananes. / Ajouter la farine, la levure et la vanille, puis mélanger doucement. / Verser dans le moule et cuire 35 à 40 minutes. Vérifier avec une pointe de couteau ; elle peut être humide mais sans pâte crue. / Laisser tiédir puis couper en tranches.","🍌","Idéal pour utiliser des bananes très mûres, à condition qu’elles soient encore saines.");
  add("dessert","Gâteau marbré vanille-chocolat",55,"four","farine:175;oeuf:2;sucre:110;beurre:95;lait:100;chocolat:85;levure:8;vanille:4","Préchauffer le four à 175 °C et préparer un petit moule à cake beurré. / Faire fondre le beurre puis le chocolat séparément, à feu doux ou par séquences courtes au micro-ondes. / Fouetter œufs et sucre. Ajouter le beurre, le lait, la farine et la levure. / Séparer la pâte en deux saladiers : incorporer la vanille dans le premier et le chocolat fondu dans le second. / Verser alternativement les pâtes claires et foncées dans le moule ; passer une fourchette une seule fois dans la pâte pour dessiner les marbrures. / Cuire environ 35 à 40 minutes, vérifier la cuisson au centre puis laisser tiédir avant de démouler.","🍫","Le marbrage doit rester léger pour garder deux couleurs distinctes.");
  add("dessert","Fondant au chocolat facile",30,"four","chocolat:150;beurre:95;oeuf:3;sucre:75;farine:45","Préchauffer le four à 180 °C et beurrer un petit moule de 16 à 18 cm. / Faire fondre le chocolat avec le beurre à feu doux, mélanger puis laisser tiédir. / Dans un saladier, fouetter les œufs avec le sucre pendant une minute. / Ajouter le chocolat fondu, puis la farine ; mélanger jusqu’à ce que la pâte soit lisse. / Verser dans le moule et cuire environ 18 à 22 minutes. Le gâteau doit être pris sur les bords ; prolonger un peu la cuisson pour un centre moins fondant. / Laisser tiédir 10 minutes avant de découper et conserver au frais s’il en reste.","🍫","Pour les personnes vulnérables, privilégier une cuisson bien prise au centre.");
  add("dessert","Gâteau aux poires rapide",45,"four","poire:3;farine:150;oeuf:2;sucre:90;beurre:75;lait:70;levure:7","Préchauffer le four à 180 °C et beurrer un moule de 18 cm. / Éplucher les poires, retirer les pépins et les couper en petits dés. / Fouetter les œufs avec le sucre, ajouter le beurre fondu puis le lait. / Incorporer farine et levure, puis mélanger délicatement les dés de poire à la pâte. / Verser dans le moule et cuire 30 à 35 minutes. Vérifier la cuisson au centre. / Laisser tiédir avant de servir, avec éventuellement un peu de fromage blanc.","🍐","Fonctionne aussi avec des poires très mûres mais non abîmées.");
  add("dessert","Gâteau aux amandes rapide",40,"four","amandes:110;farine:65;sucre:85;oeuf:2;beurre:85;levure:5","Préchauffer le four à 175 °C et beurrer un petit moule. / Mixer les amandes pour obtenir une poudre fine si elles sont entières. / Fouetter les œufs et le sucre, puis ajouter le beurre fondu tiède. / Incorporer les amandes moulues, la farine et la levure et mélanger. / Verser dans le moule, lisser et cuire 25 à 30 minutes jusqu’à ce que la surface soit dorée. / Vérifier la cuisson au centre et laisser refroidir avant de démouler.","🥜","Contient des fruits à coque. Adapter en fonction des allergies.");
  add("dessert","Cake à l’orange facile",50,"four","orange:2;farine:170;sucre:100;oeuf:2;huile:65;levure:8","Préchauffer le four à 180 °C et huiler un petit moule à cake. / Laver les oranges. Prélever finement le zeste de l’une d’elles, puis presser les deux pour obtenir environ 100 ml de jus. / Fouetter les œufs avec le sucre, ajouter l’huile, le jus et le zeste. / Incorporer farine et levure, mélanger délicatement puis verser dans le moule. / Cuire 30 à 35 minutes. Vérifier la cuisson avec un couteau. / Laisser tiédir avant de servir. Pour un goût plus marqué, arroser avec une cuillère de jus réservé.","🍊","Éviter de prélever la partie blanche de la peau, plus amère.");
  add("dessert","Gâteau à la noix de coco",45,"four","noix_coco:110;farine:100;sucre:90;oeuf:2;lait:110;beurre:70;levure:8","Préchauffer le four à 180 °C et beurrer un moule de 18 cm. / Fouetter les œufs avec le sucre, puis ajouter le beurre fondu tiédi et le lait. / Incorporer la noix de coco râpée, la farine et la levure. / Verser la pâte dans le moule en lissant la surface. / Enfourner 28 à 32 minutes, jusqu’à ce que le gâteau soit légèrement doré et cuit au centre. / Laisser refroidir avant de couper en parts.","🥥","Une cuillère de lait supplémentaire peut assouplir la pâte si la coco absorbe beaucoup.");
  add("dessert","Muffins chocolat faciles",35,"four","farine:155;sucre:80;oeuf:1;lait:130;huile:55;levure:8;chocolat:95","Préchauffer le four à 180 °C et disposer 6 caissettes dans un moule à muffins. / Hacher le chocolat en petits morceaux pour obtenir des pépites. / Dans un saladier, mélanger farine, levure et sucre. Dans un autre, battre l’œuf avec le lait et l’huile. / Verser le mélange liquide dans les poudres et remuer brièvement, sans chercher une pâte totalement lisse. Ajouter le chocolat. / Répartir dans les caissettes aux deux tiers et cuire 17 à 20 minutes. / Vérifier que les muffins sont cuits au centre avant de les laisser refroidir sur une grille.","🧁","Donne environ 6 petits muffins, à partager selon l’appétit.");
  add("dessert","Cake au miel",50,"four","farine:165;oeuf:2;miel:95;lait:95;beurre:75;levure:7;cannelle:2","Préchauffer le four à 175 °C et beurrer un petit moule à cake. / Faire tiédir le lait avec le miel, sans faire bouillir, pour le liquéfier. / Battre les œufs avec le beurre fondu, puis incorporer le mélange lait-miel. / Ajouter farine, levure et cannelle puis remuer jusqu’à ce que la pâte soit homogène. / Verser dans le moule et cuire environ 32 à 38 minutes. / Vérifier au couteau et laisser tiédir avant de découper.","🍯","Le miel est déconseillé aux enfants de moins de 1 an.");
  add("dessert","Gâteau de semoule au lait",40,"casserole","semoule:110;lait:500;sucre:75;vanille:5;beurre:15;oeuf:1","Faire chauffer le lait avec le sucre et la vanille dans une casserole à fond épais. / Verser la semoule en pluie dans le lait frémissant tout en fouettant pour éviter les grumeaux. / Cuire à feu doux 7 à 9 minutes en remuant, jusqu’à épaississement. / Hors du feu, incorporer le beurre. Battre l’œuf dans un bol, le mélanger avec quelques cuillères de semoule chaude, puis reverser le tout dans la casserole. / Remettre sur feu très doux quelques minutes en remuant constamment, jusqu’à cuisson complète de l’œuf et texture ferme. / Répartir dans des ramequins, laisser refroidir puis placer au frais avant de servir.","🥣","Dessert à préparer quelques heures à l’avance pour une meilleure tenue.");
  add("dessert","Gâteau au fromage blanc sans pâte",55,"four","fromage_blanc:350;oeuf:3;sucre:90;farine:60;vanille:3;citron:1","Préchauffer le four à 170 °C et chemiser un petit moule de papier cuisson. / Égoutter légèrement le fromage blanc si sa texture est très liquide. / Fouetter les œufs avec le sucre et la vanille, puis incorporer le fromage blanc. / Ajouter la farine tamisée et un peu de zeste fin de citron. Mélanger sans laisser de grumeaux. / Verser dans le moule et cuire 35 à 40 minutes : le centre doit être pris, même s’il reste souple. / Laisser refroidir, puis mettre au réfrigérateur au moins une heure avant de démouler et servir.","🍰","Conserver au réfrigérateur et consommer rapidement.");
  add("dessert","Cake aux carottes et à la cannelle",55,"four","carotte:220;farine:145;sucre:95;oeuf:2;huile:70;levure:8;cannelle:4;noix:50","Préchauffer le four à 175 °C et préparer un petit moule à cake. / Éplucher puis râper finement les carottes. Concasser les noix si elles sont entières. / Fouetter les œufs avec le sucre et l’huile. Incorporer farine, levure et cannelle. / Ajouter les carottes râpées et les noix puis mélanger doucement. / Verser dans le moule et cuire 35 à 40 minutes ; vérifier la cuisson au centre. / Laisser refroidir complètement avant de trancher.","🥕","Les noix sont facultatives mais figurent dans la liste de courses de cette version.");
  add("dessert","Brownie facile aux noix",40,"four","chocolat:155;beurre:100;sucre:100;oeuf:2;farine:65;noix:75","Préchauffer le four à 175 °C et tapisser un petit moule carré de papier cuisson. / Faire fondre doucement le chocolat avec le beurre, puis laisser tiédir. / Fouetter les œufs et le sucre, verser le chocolat fondu en remuant. / Incorporer la farine puis les noix grossièrement concassées. / Étaler la pâte dans le moule et cuire 23 à 27 minutes, selon l’épaisseur. Le centre doit être pris ; prolonger légèrement pour un brownie moins fondant. / Laisser refroidir avant de découper en petits carrés.","🍫","Contient des noix ; adapter selon les allergies.");
  add("dessert","Gâteau chocolat-banane",45,"four","banane:2;chocolat:125;farine:120;oeuf:2;sucre:65;beurre:75;levure:7","Préchauffer le four à 180 °C et beurrer un petit moule rond. / Faire fondre le chocolat avec le beurre puis laisser tiédir. / Écraser les bananes et les incorporer au mélange chocolaté. / Fouetter les œufs et le sucre, ajouter la préparation chocolat-banane puis la farine et la levure. / Verser dans le moule et cuire 25 à 30 minutes, jusqu’à ce qu’une pointe de couteau ressorte sans pâte crue. / Laisser reposer 10 minutes avant de démouler.","🍌","Utiliser des bananes bien mûres pour une texture moelleuse.");
  add("dessert","Gâteau renversé aux pommes",55,"four","pomme:3;farine:160;sucre:105;oeuf:2;beurre:90;lait:85;levure:8","Préchauffer le four à 180 °C et beurrer un moule de 18 à 20 cm. / Éplucher les pommes, retirer les pépins et couper en fines lamelles. Répartir 25 g de sucre au fond du moule, puis disposer les pommes par-dessus. / Fouetter les œufs avec le reste de sucre. Incorporer le beurre fondu puis le lait. / Ajouter farine et levure en mélangeant jusqu’à obtenir une pâte lisse. Verser délicatement sur les pommes. / Cuire 32 à 38 minutes. Vérifier la cuisson au centre et laisser reposer 10 minutes. / Poser une assiette sur le moule, retourner d’un geste sûr et retirer le moule avec précaution car le caramel et le moule restent chauds.","🍎","Pour un démoulage plus facile, chemiser le fond du moule de papier cuisson.");
  add("dessert","Rochers coco maison",30,"four","noix_coco:125;sucre:85;oeuf:2","Préchauffer le four à 170 °C et recouvrir une plaque de papier cuisson. / Séparer les blancs des jaunes d’œufs ; garder les jaunes pour une autre préparation bien cuite. / Mélanger les blancs avec le sucre et la noix de coco jusqu’à obtenir une pâte qui se tient. / Former 8 à 10 petits tas en forme de rochers avec les mains légèrement humides. / Enfourner 12 à 16 minutes, jusqu’à ce que les pointes soient dorées et que les rochers soient cuits. / Laisser refroidir complètement sur la plaque avant de décoller délicatement.","🥥","Utilise seulement les blancs ; les jaunes restants ne sont pas déduits du stock automatiquement.");
  add("dessert","Gâteau aux fraises simple",45,"four","fraise:250;farine:145;sucre:95;oeuf:2;lait:90;beurre:75;levure:7","Préchauffer le four à 180 °C et beurrer un moule de 18 cm. / Laver rapidement les fraises, les sécher, les équeuter et les couper en deux. / Fouetter les œufs avec le sucre, ajouter le beurre fondu tiédi et le lait. / Incorporer la farine et la levure, verser dans le moule. / Répartir les fraises sur la pâte sans les enfoncer entièrement. / Cuire 30 à 35 minutes, vérifier la cuisson au centre et laisser tiédir avant de découper.","🍓","Bien sécher les fraises pour éviter un gâteau trop humide.");

  // V0.4 : recettes originales familiales, régionales et inspirations du monde.
  add("dessert","Gâteau express à la vanille",40,"four","farine:150;sucre:90;oeuf:2;lait:100;beurre:65;levure:7;vanille:4","Préchauffer le four à 180 °C et beurrer un moule rond de 18 cm. / Battre les œufs et le sucre 2 minutes pour éclaircir le mélange. / Incorporer le beurre fondu tiédi, le lait puis la vanille. / Ajouter farine et levure en plusieurs fois et mélanger sans trop travailler la pâte. / Verser dans le moule et cuire 25 à 30 minutes. La pointe d’un couteau doit ressortir sans pâte crue. / Laisser reposer 10 minutes puis démouler sur une grille.","🍰","Simple et économique.","france","");
  add("dessert","Gâteau pomme-noisette",45,"four","pomme:2;noisette:80;farine:105;sucre:85;oeuf:2;huile:60;levure:7","Préchauffer le four à 180 °C et préparer un petit moule rond. / Éplucher les pommes et les couper en petits morceaux. / Fouetter les œufs avec le sucre puis incorporer l’huile. / Mélanger farine, levure et noisettes en poudre ; les incorporer au mélange liquide. / Ajouter les pommes et verser dans le moule. / Cuire 30 à 35 minutes, vérifier la cuisson au centre et laisser tiédir.","🍎","Contient des noisettes.","france","");
  add("dessert","Cake au citron et aux framboises",45,"four","citron:1;framboise:120;farine:150;sucre:85;oeuf:2;beurre:85;lait:65;levure:7","Préchauffer le four à 175 °C et beurrer un petit moule à cake. / Laver le citron, prélever son zeste fin et presser la moitié du jus. / Fouetter les œufs et le sucre puis ajouter le beurre fondu tiédi. / Ajouter farine, levure, lait, zeste et un peu de jus. / Incorporer délicatement les framboises pour ne pas les écraser. / Enfourner 32 à 38 minutes ; vérifier la cuisson au centre et laisser refroidir avant de trancher.","🍋","","france","");
  add("dessert","Muffins nature moelleux",35,"four","farine:160;sucre:85;oeuf:1;lait:140;beurre:70;levure:8;vanille:3","Préchauffer le four à 180 °C et préparer six petits moules à muffins. / Mélanger dans un saladier farine, sucre et levure. / Dans un autre bol, fouetter l’œuf avec le lait, le beurre fondu tiédi et la vanille. / Verser les liquides dans les poudres et mélanger brièvement : quelques grumeaux sont normaux. / Répartir la pâte aux deux tiers des moules et cuire 18 à 22 minutes. / Vérifier la cuisson au centre et laisser reposer quelques minutes avant de démouler.","🧁","Donne environ six petits muffins.","france","");
  add("dessert","Cake aux pépites de chocolat",50,"four","farine:170;sucre:95;oeuf:2;beurre:90;lait:80;levure:8;chocolat:95","Préchauffer le four à 175 °C et beurrer un petit moule à cake. / Hacher le chocolat en pépites et réserver. / Fouetter les œufs avec le sucre puis ajouter le beurre fondu tiédi et le lait. / Ajouter la farine et la levure sans trop mélanger puis incorporer les pépites. / Verser dans le moule et cuire 35 à 40 minutes, selon son épaisseur. / Vérifier le centre avec un couteau et laisser refroidir avant de trancher.","🍫","","france","");
  add("dessert","Gâteau aux poires et chocolat",45,"four","poire:2;farine:130;chocolat:110;beurre:70;sucre:75;oeuf:2;levure:7","Préchauffer le four à 180 °C et préparer un moule de 18 cm. / Faire fondre doucement le chocolat avec le beurre, puis laisser tiédir. / Éplucher et couper les poires en petits morceaux. / Battre les œufs avec le sucre, verser le chocolat fondu puis ajouter farine et levure. / Incorporer les poires et verser dans le moule. / Cuire 27 à 33 minutes, vérifier le centre et laisser tiédir avant de servir.","🍐","","france","");
  add("dessert","Sablés faciles au beurre",40,"four","farine:180;beurre:100;sucre:70;oeuf:1;vanille:2","Préchauffer le four à 170 °C et recouvrir une plaque de papier cuisson. / Travailler le beurre ramolli avec le sucre à la fourchette. / Incorporer l’œuf, la vanille puis la farine pour former une pâte souple. / Former un disque et réserver 10 minutes au frais si la pâte colle. / Étaler sur environ 5 mm et découper des formes à l’emporte-pièce. / Cuire 12 à 15 minutes jusqu’à légère coloration et laisser refroidir pour les raffermir.","🍪","Environ 15 petits sablés.","france","");
  add("dessert","Gâteau à la confiture",40,"four","farine:150;sucre:70;oeuf:2;lait:110;huile:65;levure:7;confiture:100","Préchauffer le four à 180 °C et graisser un moule de 18 cm. / Fouetter les œufs avec le sucre puis verser le lait et l’huile. / Incorporer la farine et la levure jusqu’à obtenir une pâte lisse. / Verser les deux tiers de pâte dans le moule puis déposer la confiture par petites touches. / Recouvrir du reste de pâte en traçant quelques marbrures avec une cuillère. / Cuire 27 à 32 minutes, vérifier le centre et laisser tiédir avant de démouler.","🍓","","france","");
  add("dessert","Gâteau aux amandes et miel",45,"four","amandes:115;farine:85;miel:85;oeuf:2;beurre:80;levure:7","Préchauffer le four à 175 °C et préparer un moule de 18 cm. / Faire fondre le beurre puis le laisser tiédir. / Fouetter les œufs avec le miel jusqu’à homogénéité. / Incorporer beurre, amandes en poudre, farine puis levure. / Verser dans le moule et lisser la surface. / Cuire 27 à 32 minutes et vérifier que la pointe du couteau ressort sans pâte crue.","🍯","Pas de miel pour les enfants de moins d’un an.","france","");
  add("dessert","Petits financiers aux amandes",35,"four","amandes:80;farine:45;sucre_glace:85;beurre:80;oeuf:3","Préchauffer le four à 180 °C et graisser de petits moules. / Faire fondre doucement le beurre jusqu’à légère couleur noisette puis laisser tiédir. / Séparer les blancs des jaunes ; réserver les jaunes pour une autre préparation bien cuite. / Mélanger amandes en poudre, farine et sucre glace dans un saladier. / Incorporer les blancs non montés puis le beurre tiède. / Verser dans les moules et cuire 12 à 16 minutes ; laisser refroidir avant de démouler.","🍰","Utilise les blancs de trois œufs : les jaunes restants ne sont pas suivis séparément dans le stock.","france","");
  add("dessert","Clafoutis aux poires",50,"four","poire:3;oeuf:3;farine:80;lait:240;sucre:80;beurre:20;vanille:3","Préchauffer le four à 180 °C et beurrer un petit plat à gratin. / Éplucher et couper les poires en tranches puis les répartir dans le plat. / Fouetter les œufs avec le sucre et la vanille. / Incorporer la farine puis verser progressivement le lait pour éviter les grumeaux. / Verser l’appareil sur les poires et enfourner 30 à 35 minutes. / Le centre doit être pris ; servir tiède ou froid.","🍐","","france","");
  add("dessert","Madeleines au citron",45,"four","farine:120;sucre:90;oeuf:2;beurre:100;levure:5;citron:1","Faire fondre le beurre puis le laisser tiédir. / Battre les œufs avec le sucre, puis ajouter le zeste fin du citron. / Incorporer farine et levure, puis verser le beurre fondu. / Placer la pâte au frais 15 minutes et préchauffer le four à 200 °C. / Beurrer les empreintes à madeleines et les remplir aux trois quarts. / Cuire 8 à 11 minutes en surveillant : les madeleines doivent gonfler et dorer.","🍋","Matériel : moule à madeleines.","france","");
  add("dessert","Crumble pommes-poires",45,"four","pomme:2;poire:2;farine:110;beurre:85;sucre:75;cannelle:2","Préchauffer le four à 180 °C et beurrer un petit plat. / Éplucher les pommes et poires, retirer les pépins et couper en cubes. / Répartir les fruits dans le fond du plat et saupoudrer de cannelle. / Mélanger du bout des doigts farine, beurre froid en dés et sucre pour faire des miettes. / Parsemer les miettes sur les fruits sans tasser. / Enfourner 25 à 30 minutes jusqu’à ce que la surface soit dorée et les fruits tendres.","🍎","","france","");
  add("dessert","Cookies chocolat-noisettes",35,"four","farine:170;sucre_roux:95;beurre:95;oeuf:1;levure:5;chocolat:100;noisette:70","Préchauffer le four à 175 °C et préparer une plaque avec papier cuisson. / Mélanger le beurre mou et le sucre roux puis incorporer l’œuf. / Ajouter farine et levure sans trop travailler. / Incorporer le chocolat concassé et les noisettes grossièrement hachées. / Former des petites boules bien espacées et les aplatir légèrement. / Cuire 11 à 14 minutes : laisser refroidir sur la plaque pour que les cookies raffermissent.","🍪","Contient des fruits à coque.","france","");
  add("dessert","Riz au lait de coco vanillé",40,"casserole","riz_rond:115;lait_coco:350;lait:300;sucre:65;vanille:4","Rincer rapidement le riz rond à l’eau froide. / Verser lait de coco, lait et vanille dans une casserole à fond épais. / Chauffer jusqu’au frémissement puis ajouter le riz et le sucre. / Laisser mijoter à feu doux 30 à 35 minutes en remuant régulièrement. / Rajouter un petit filet de lait si le riz est encore ferme et le mélange trop épais. / Répartir dans des bols et laisser tiédir ou refroidir avant de servir.","🍚","Variation parfumée à la noix de coco.","france","");
  add("dessert","Gâteau sans four aux biscuits et chocolat",25,"froid","biscuit:180;chocolat:150;beurre:85;lait:100","Émietter les biscuits en petits morceaux dans un saladier. / Faire fondre doucement le chocolat et le beurre ensemble, puis incorporer le lait. / Verser la préparation sur les biscuits et mélanger pour bien les enrober. / Tasser dans un petit moule chemisé de papier cuisson. / Placer au réfrigérateur au moins 3 heures jusqu’à ce que l’ensemble soit ferme. / Démouler et couper avec un couteau chaud essuyé entre les parts.","🍫","25 minutes de préparation, plus 3 heures au frais.","france","");
  add("plat","Flamiche aux poireaux du Nord",60,"four","pate_brisee:1;poireau:3;creme:220;oeuf:2;beurre:25;fromage:70","Préchauffer le four à 190 °C et garnir un moule de pâte brisée. / Nettoyer soigneusement les poireaux puis les émincer finement. / Faire fondre le beurre dans une poêle et cuire les poireaux à feu doux 15 minutes sans coloration. / Battre les œufs et la crème, puis ajouter les poireaux tiédis et le fromage. / Verser la garniture sur la pâte et enfourner 30 à 35 minutes. / Laisser reposer 5 minutes avant de découper et servir avec une salade.","🥧","Inspiration du Nord de la France.","france","Nord");
  add("plat","Tarte au maroilles façon Nord",50,"four","pate_brisee:1;maroilles:160;creme:160;oeuf:1","Préchauffer le four à 200 °C et dérouler la pâte dans un petit moule. / Piquer le fond avec une fourchette et le précuire 7 minutes. / Découper le maroilles en fines tranches, croûte comprise si elle est propre. / Mélanger l’œuf et la crème dans un bol. / Répartir le fromage sur la pâte et verser la crème par-dessus. / Cuire encore 22 à 28 minutes jusqu’à ce que le dessus soit doré ; laisser tiédir.","🧀","Spécialité du Nord ; fromage à forte saveur.","france","Nord");
  add("plat","Galettes bretonnes au jambon et œuf",35,"poêle","farine_sarrasin:160;oeuf:3;lait:80;beurre:25;jambon:2;fromage:80","Mélanger la farine avec environ 250 ml d’eau, le lait et une pincée de sel pour obtenir une pâte fluide. / Laisser reposer 10 minutes et chauffer une grande poêle légèrement beurrée. / Verser une petite louche de pâte puis l’étaler finement. / Cuire 2 minutes puis retourner la galette ; ajouter du fromage et une tranche de jambon. / Casser un œuf au centre de chaque galette et cuire jusqu’à ce que le blanc soit pris. / Replier les bords en carré et servir immédiatement.","🥞","Version familiale à la farine de sarrasin ; respecter les indications du fabricant pour la texture de la pâte.","france","Bretagne");
  add("plat","Piperade basquaise aux œufs",35,"poêle","poivron:3;tomate:4;oignon:1;ail:8;oeuf:4;huile:20;herbes:5","Épépiner les poivrons et les couper en lanières fines. / Émincer l’oignon et couper les tomates en petits dés. / Faire revenir oignon et poivrons dans une grande poêle avec l’huile pendant 10 minutes. / Ajouter l’ail, les tomates et les herbes puis mijoter 12 minutes à feu doux. / Battre les œufs dans un bol et les verser sur les légumes. / Remuer doucement jusqu’à ce que les œufs soient cuits et servir avec du pain.","🍗","Inspiration basque, version familiale aux œufs.","france","Pays basque");
  add("plat","Aligot facile au fromage",40,"casserole","pomme_terre:550;fromage:240;creme:120;beurre:35;ail:6","Éplucher les pommes de terre et les couper en morceaux réguliers. / Les cuire dans l’eau bouillante environ 20 minutes jusqu’à ce qu’elles soient tendres. / Bien égoutter puis écraser très finement les pommes de terre encore chaudes. / Chauffer la crème avec l’ail écrasé et le beurre, puis l’incorporer à la purée. / Ajouter le fromage râpé peu à peu sur feu très doux en remuant énergiquement. / Servir immédiatement lorsque la préparation devient lisse et filante.","🧀","Version familiale à l’emmental : la préparation traditionnelle utilise de la tome fraîche.","france","Aubrac");
  add("plat","Tarte flambée alsacienne simplifiée",40,"four","pate_brisee:1;fromage_blanc:130;creme:100;lardons:120;oignon:1","Préchauffer le four à 230 °C et placer une plaque à mi-hauteur. / Étaler la pâte le plus finement possible sur du papier cuisson. / Mélanger fromage blanc et crème puis étaler sur la pâte. / Émincer très finement l’oignon et répartir avec les lardons. / Enfourner 12 à 17 minutes jusqu’à ce que les bords dorent et que les lardons soient cuits. / Couper en parts et servir immédiatement.","🥧","Adaptation familiale avec pâte brisée ; pâte fine traditionnelle différente.","france","Alsace");
  add("plat","Poulet à la provençale",45,"casserole","poulet:390;tomate:4;poivron:1;olives:90;oignon:1;ail:8;huile:20;herbes:6","Couper les tomates en cubes, émincer l’oignon et le poivron. / Faire dorer le poulet dans une cocotte avec l’huile, puis le réserver. / Faire suer l’oignon et le poivron 5 minutes, ajouter l’ail et les tomates. / Remettre le poulet, ajouter les herbes, couvrir et laisser mijoter 25 minutes. / Ajouter les olives 5 minutes avant la fin pour conserver leur texture. / Vérifier la cuisson complète du poulet puis servir avec du riz ou de la semoule.","🍅","Inspiration de Provence.","france","Provence");
  add("plat","Gratin savoyard de pommes de terre",60,"four","pomme_terre:650;fromage:170;oignon:1;bouillon:1;beurre:25","Préchauffer le four à 190 °C et beurrer un plat. / Éplucher les pommes de terre puis les trancher finement. / Émincer l’oignon et préparer environ 350 ml de bouillon chaud. / Alterner dans le plat pommes de terre, oignon et la moitié du fromage. / Verser le bouillon sans submerger les pommes de terre, puis ajouter le reste du fromage. / Cuire 45 à 50 minutes jusqu’à ce que le cœur soit tendre et la surface dorée.","🥔","Inspiration savoyarde, sans crème.","france","Savoie");
  add("dessert","Far breton aux pruneaux",60,"four","farine:120;oeuf:3;lait:450;sucre:100;beurre:25;pruneaux:140","Préchauffer le four à 180 °C et beurrer généreusement un petit plat. / Couper les pruneaux dénoyautés en deux et les réserver. / Fouetter les œufs avec le sucre puis ajouter la farine petit à petit. / Verser le lait progressivement pour obtenir une pâte fluide, sans grumeaux. / Répartir les pruneaux dans le plat, verser la pâte et enfourner 40 à 45 minutes. / Le centre doit être pris ; laisser tiédir et servir en parts.","🍮","Far breton aux pruneaux, version maison.","france","Bretagne");
  add("plat","Paella familiale au poulet",55,"poêle","riz_rond:190;poulet:300;poivron:1;petits_pois:110;tomate:2;oignon:1;bouillon:1;paprika:4;huile:20","Couper le poulet en morceaux, émincer l’oignon et le poivron. / Dans une large poêle, faire dorer le poulet dans l’huile puis le réserver. / Faire revenir oignon et poivron, ajouter les tomates et le paprika. / Verser le riz puis environ 500 ml de bouillon chaud, disposer le poulet dessus. / Laisser mijoter à feu modéré 20 minutes sans trop remuer ; ajouter les petits pois à mi-cuisson. / Veiller à ce que le riz soit tendre et le poulet complètement cuit, laisser reposer 5 minutes.","🥘","Version familiale simplifiée, inspirée des plats de riz espagnols.","espagne","");
  add("plat","Croquetas espagnoles au jambon",60,"poêle","jambon:2;lait:350;farine:70;beurre:60;oeuf:1;chapelure:110;huile:140","Hacher finement le jambon et faire fondre le beurre dans une casserole. / Ajouter la farine, cuire 2 minutes en remuant, puis verser le lait peu à peu. / Mélanger jusqu’à obtenir une béchamel très épaisse ; incorporer le jambon. / Étaler dans un plat, filmer au contact et refroidir complètement au moins 2 heures. / Former des petites croquettes puis les passer dans l’œuf battu et la chapelure. / Dorer par petites fournées dans l’huile chaude en surveillant, égoutter sur du papier absorbant.","🥔","Temps indiqué hors repos au froid : prévoir au moins 2 heures supplémentaires.","espagne","");
  add("plat","Pisto espagnol de légumes",40,"poêle","courgette:350;poivron:2;tomate:3;oignon:1;ail:6;huile:25;oeuf:2","Laver les légumes et les couper en petits dés réguliers. / Faire revenir oignon et poivrons dans l’huile pendant 7 minutes. / Ajouter les courgettes et poursuivre la cuisson 8 minutes. / Incorporer les tomates et l’ail puis laisser réduire 15 minutes à feu doux. / Casser les œufs sur les légumes et couvrir jusqu’à ce que les blancs soient pris. / Servir chaud avec du pain ; adapter la cuisson des œufs selon les convives.","🍅","Inspiration espagnole.","espagne","");
  add("plat","Tajine de boulettes aux petits pois",45,"casserole","boeuf:340;petits_pois:230;oignon:1;ail:8;tomate:2;cumin:4;curcuma:3;huile:20;bouillon:1","Émincer la moitié de l’oignon et écraser l’ail. / Mélanger la viande hachée avec l’oignon et le cumin puis façonner de petites boulettes. / Faire revenir le reste d’oignon et l’ail dans l’huile, ajouter curcuma et tomates en cubes. / Verser 250 ml de bouillon et laisser mijoter 8 minutes. / Plonger les boulettes dans la sauce, couvrir et cuire 15 minutes. / Ajouter les petits pois, laisser mijoter 8 minutes de plus et vérifier la cuisson complète des boulettes.","🍋","Interprétation familiale inspirée des tajines marocains.","maroc","");
  add("plat","Keftas marocaines à la tomate",40,"poêle","boeuf:340;coulis:300;oignon:1;ail:8;cumin:5;paprika:4;coriandre:10;huile:15","Émincer finement la moitié de l’oignon et hacher la coriandre. / Mélanger la viande avec l’oignon haché, le cumin et la moitié de la coriandre. / Former de petites boulettes régulières avec les mains propres. / Faire revenir le reste d’oignon dans l’huile, ajouter ail, paprika et coulis. / Déposer les boulettes dans la sauce, couvrir et laisser mijoter 18 à 20 minutes. / Vérifier la cuisson à cœur des boulettes puis terminer avec le reste de coriandre.","🍲","Version familiale sans œuf, inspirée de la cuisine marocaine.","maroc","");
  add("entree","Harira végétarienne simplifiée",45,"casserole","lentilles:100;pois_chiches:170;tomate:2;coulis:130;oignon:1;carotte:120;coriandre:8;cumin:3;bouillon:1","Rincer les lentilles et couper oignon, carotte et tomates en petits dés. / Faire revenir l’oignon avec un peu d’eau puis ajouter carotte, tomates et cumin. / Ajouter les lentilles, le bouillon et environ 600 ml d’eau. / Laisser mijoter 25 à 30 minutes jusqu’à ce que les lentilles soient tendres. / Incorporer les pois chiches cuits et le coulis puis chauffer 5 minutes. / Parsemer de coriandre et servir chaud.","🥣","Version végétarienne simplifiée inspirée de la harira marocaine.","maroc","");
  add("plat","Curry de poulet indien doux",40,"casserole","poulet:380;lait_coco:280;coulis:200;oignon:1;ail:6;gingembre:12;curry:8;huile:15","Couper le poulet en morceaux réguliers, émincer l’oignon et râper le gingembre. / Chauffer l’huile dans une casserole et attendrir l’oignon 5 minutes. / Ajouter ail, gingembre et curry puis remuer une minute sans brûler les épices. / Incorporer le poulet et le faire revenir 5 minutes. / Ajouter le coulis et le lait de coco, couvrir et cuire 18 à 20 minutes à feu doux. / Vérifier la cuisson complète du poulet et servir avec du riz.","🍛","Inspiration indienne familiale, volontairement peu pimentée.","inde","");
  add("plat","Chana masala simplifié",35,"casserole","pois_chiches:360;coulis:280;oignon:1;ail:8;gingembre:10;cumin:5;curcuma:3;huile:15;coriandre:8","Rincer et égoutter les pois chiches déjà cuits. / Émincer l’oignon, hacher l’ail et râper le gingembre. / Faire revenir l’oignon dans l’huile 6 minutes puis ajouter ail, gingembre, cumin et curcuma. / Incorporer le coulis et un demi-verre d’eau ; mijoter 8 minutes. / Ajouter les pois chiches et cuire encore 12 minutes en remuant. / Parsemer de coriandre et servir avec du riz ou du pain.","🫘","Inspiration indienne végétalienne.","inde","");
  add("plat","Aloo gobi indien familial",40,"poêle","pomme_terre:450;chou_fleur:400;oignon:1;ail:8;gingembre:10;curcuma:3;cumin:4;huile:20","Éplucher les pommes de terre, les couper en petits dés et détailler le chou-fleur. / Faire précuire les pommes de terre 6 minutes dans de l’eau frémissante puis égoutter. / Chauffer l’huile, faire revenir l’oignon 5 minutes puis ajouter ail et gingembre. / Ajouter cumin et curcuma et remuer 30 secondes. / Incorporer pommes de terre et chou-fleur avec un petit fond d’eau, couvrir 15 minutes. / Veiller à ce que les légumes soient tendres puis servir chaud.","🥔","Inspiré de la cuisine indienne.","inde","");
  add("plat","Poulet yassa simplifié",65,"casserole","poulet:420;oignon:3;citron:2;moutarde:25;huile:20;ail:6;riz:150","Émincer les oignons et presser les citrons. / Mélanger le poulet avec le jus de citron, la moutarde et la moitié des oignons ; laisser mariner au frais 30 minutes. / Faire dorer le poulet dans l’huile puis le réserver. / Faire fondre les oignons restants et la marinade dans la cocotte 10 minutes. / Remettre le poulet, ajouter un fond d’eau et mijoter à couvert 25 minutes. / Vérifier la cuisson du poulet et servir avec le riz cuit selon l’emballage.","🍗","Inspiré du yassa sénégalais. Prévoir 30 minutes de marinade en plus du temps affiché.","senegal","");
  add("plat","Mafé de poulet familial",50,"casserole","poulet:360;beurre_cacahuete:110;coulis:180;carotte:200;pomme_terre:300;oignon:1;huile:15;bouillon:1","Émincer l’oignon, couper les carottes et pommes de terre en petits morceaux. / Dorer le poulet avec l’huile dans une cocotte et le réserver. / Faire revenir l’oignon puis ajouter les carottes, les pommes de terre et le coulis. / Diluer le beurre de cacahuète dans 350 ml de bouillon chaud pour obtenir une sauce lisse. / Remettre le poulet et verser la sauce ; laisser mijoter environ 25 minutes en remuant. / Vérifier la cuisson du poulet et la tendreté des légumes puis servir avec du riz si souhaité.","🥜","Inspiré du mafé d’Afrique de l’Ouest. Attention : contient des arachides.","senegal","");
  add("plat","Riz jollof familial aux légumes",45,"casserole","riz:190;coulis:300;poivron:1;oignon:1;ail:8;carotte:140;paprika:5;huile:20;bouillon:1","Émincer l’oignon et l’ail puis couper poivron et carotte en petits dés. / Faire revenir oignon et légumes dans l’huile pendant 7 minutes. / Ajouter le paprika et le coulis, laisser réduire 5 minutes. / Incorporer le riz rincé puis environ 330 ml de bouillon chaud. / Couvrir et laisser cuire à feu doux 18 à 22 minutes, jusqu’à absorption et cuisson complète du riz. / Laisser reposer 5 minutes hors du feu et égrainer avant de servir.","🍚","Inspiration ouest-africaine, version végétale simplifiée.","cote_ivoire","");
  add("plat","Nouilles sautées japonaises façon yakisoba",30,"poêle","nouilles:210;chou_blanc:170;carotte:140;oignon:1;sauce_soja:35;huile:15;huile_sesame:10","Cuire les nouilles selon leur emballage puis les égoutter. / Émincer finement le chou et l’oignon, couper les carottes en bâtonnets. / Faire chauffer l’huile dans une grande poêle et faire sauter les légumes 6 à 8 minutes. / Ajouter les nouilles égouttées et les faire revenir 2 minutes. / Verser la sauce soja et l’huile de sésame puis mélanger pour enrober. / Servir immédiatement lorsque les nouilles sont bien chaudes.","🍜","Inspiration japonaise ; vérifier la composition de la sauce soja selon les allergies.","japon","");
  add("plat","Donburi poulet-riz maison",35,"poêle","riz:180;poulet:300;oignon:1;oeuf:2;sauce_soja:35;sucre:12;huile:10","Cuire le riz selon son emballage et le garder au chaud. / Émincer l’oignon et couper le poulet en fines bouchées. / Faire revenir l’oignon 4 minutes dans l’huile, ajouter le poulet et le saisir. / Ajouter la sauce soja, le sucre et un demi-verre d’eau puis mijoter jusqu’à cuisson complète du poulet. / Battre les œufs et les verser sur le poulet ; couvrir jusqu’à cuisson complète des œufs. / Répartir le riz dans deux bols et déposer le poulet aux œufs par-dessus.","🍚","Inspiré du bol japonais oyakodon, œufs cuits à cœur.","japon","");
  add("plat","Nouilles chinoises aux légumes",25,"poêle","nouilles:190;carotte:170;poivron:1;champignon:180;sauce_soja:40;gingembre:10;huile:20","Cuire les nouilles selon l’emballage et les égoutter. / Tailler carotte, poivron et champignons en petites lamelles. / Chauffer l’huile à feu vif dans une grande poêle. / Faire sauter les légumes 6 à 8 minutes jusqu’à ce qu’ils soient tendres mais encore légèrement fermes. / Ajouter gingembre râpé, nouilles et sauce soja. / Faire sauter encore 2 minutes et servir aussitôt.","🍜","Inspiration chinoise familiale.","chine","");
  add("plat","Poulet au gingembre et soja",30,"poêle","poulet:340;gingembre:15;sauce_soja:40;miel:25;ail:8;huile:15;riz:160","Cuire le riz selon l’emballage et le garder chaud. / Couper le poulet en fines lanières et râper le gingembre. / Chauffer l’huile dans une poêle et faire dorer le poulet 6 à 8 minutes. / Ajouter ail et gingembre puis remuer une minute. / Verser sauce soja et miel, faire réduire 3 minutes jusqu’à obtenir une sauce légère. / Vérifier la cuisson complète du poulet et servir sur le riz.","🍗","Inspiration asiatique familiale.","chine","");
  add("plat","Curry thaï doux aux légumes",35,"casserole","lait_coco:300;courgette:280;carotte:180;poivron:1;pate_curry:25;huile:15;riz:160","Cuire le riz selon l’emballage. / Couper les courgettes, carottes et poivron en bâtonnets de taille similaire. / Chauffer l’huile dans une casserole et faire revenir la pâte de curry une minute. / Verser le lait de coco et un peu d’eau puis ajouter les carottes. / Après 6 minutes, ajouter poivron et courgette, laisser mijoter jusqu’à tendreté. / Goûter et ajuster la quantité de curry selon son piquant, puis servir avec le riz.","🍛","Version familiale inspirée de la Thaïlande : les pâtes de curry peuvent être très épicées.","thailande","");
  add("plat","Quesadillas fromage et haricots",25,"poêle","pain_wrap:4;fromage:160;haricots_rouges:240;mais:100;tomate:2;huile:10","Rincer et égoutter les haricots rouges et le maïs. / Couper les tomates en petits dés et les éponger légèrement. / Répartir fromage, haricots, maïs et tomate sur deux tortillas. / Recouvrir des deux autres tortillas et presser doucement. / Cuire dans une poêle légèrement huilée 3 à 4 minutes par face à feu moyen. / Couper en quartiers et servir lorsque le fromage est fondu et la garniture bien chaude.","🌮","Inspiration mexicaine familiale.","mexique","");
  add("plat","Tacos de poulet maison",30,"poêle","pain_wrap:4;poulet:320;tomate:2;salade:100;fromage_blanc:120;paprika:4;huile:15;citron:1","Couper le poulet en petites lanières et le mélanger avec le paprika. / Faire chauffer l’huile et cuire le poulet complètement à cœur. / Laver la salade, couper les tomates en petits dés. / Mélanger fromage blanc et quelques gouttes de citron pour la sauce. / Réchauffer les tortillas dans une poêle sèche quelques secondes. / Garnir de poulet, crudités et sauce puis servir aussitôt.","🌮","Tacos familiaux d’inspiration mexicaine ; tortillas souples.","mexique","");
  add("plat","Burritos aux haricots rouges",30,"poêle","pain_wrap:4;haricots_rouges:300;riz:130;coulis:140;mais:140;fromage:100;cumin:3","Cuire le riz dans l’eau selon l’emballage. / Rincer les haricots rouges et le maïs puis les égoutter. / Réchauffer le coulis avec le cumin et les haricots pendant 8 minutes. / Ajouter le riz, le maïs et le fromage râpé puis mélanger. / Réchauffer rapidement les tortillas dans une poêle sèche. / Répartir la garniture, replier les côtés et rouler fermement avant de servir.","🌯","Inspiré de la cuisine tex-mex.","mexique","");
  add("plat","Frittata italienne courgette-parmesan",30,"poêle","oeuf:5;courgette:270;parmesan:60;oignon:1;huile:20","Couper la courgette en petits dés et émincer l’oignon. / Faire revenir oignon et courgette dans l’huile 8 minutes. / Battre les œufs avec le parmesan râpé. / Verser les œufs sur les légumes et cuire à feu doux environ 10 minutes. / Couvrir pour faire prendre le dessus sans brûler le dessous. / Vérifier que le centre est pris puis servir en parts.","🍳","Inspiration italienne, œufs cuits à cœur.","italie","");
  add("plat","Pasta alla norma simplifiée",35,"casserole","pates:190;aubergine:350;coulis:280;ail:7;huile:25;parmesan:35;herbes:6","Couper l’aubergine en dés et les saler légèrement, puis éponger. / Chauffer l’huile dans une poêle et faire dorer les aubergines environ 12 minutes. / Ajouter l’ail et le coulis puis laisser mijoter 10 minutes. / Faire cuire les pâtes dans de l’eau bouillante selon leur emballage. / Garder une petite louche d’eau de cuisson avant d’égoutter les pâtes. / Mélanger pâtes et sauce, détendre si besoin et servir avec parmesan et herbes.","🍝","Version familiale inspirée de la Sicile.","italie","");
  add("plat","Polenta crémeuse aux champignons",35,"casserole","polenta:150;champignon:300;creme:150;beurre:35;parmesan:50;oignon:1","Nettoyer les champignons puis les couper en tranches. / Faire fondre l’oignon émincé dans la moitié du beurre. / Ajouter les champignons et les faire revenir 8 minutes, puis incorporer la crème. / Préparer la polenta dans environ 550 ml d’eau chaude en suivant le temps du paquet. / Incorporer le reste de beurre et le parmesan à la polenta. / Verser la sauce aux champignons sur la polenta chaude et servir.","🍄","Polenta de maïs : vérifier le temps de cuisson indiqué sur le paquet.","italie","");
  add("plat","Riz aux olives façon portugaise",35,"casserole","riz:185;olives:120;tomate:2;poivron:1;oignon:1;ail:7;huile:18;bouillon:1","Émincer oignon et ail puis couper tomate et poivron en dés. / Faire revenir l’oignon dans l’huile 5 minutes. / Ajouter poivron, ail, tomate et olives, poursuivre 4 minutes. / Ajouter le riz rincé et mélanger aux légumes. / Verser environ 350 ml de bouillon chaud et couvrir. / Laisser cuire selon le riz jusqu’à absorption du liquide et servir.","🫒","Inspiration portugaise familiale.","portugal","");
  add("plat","Keftas à la tomate façon libanaise",40,"poêle","boeuf:350;oignon:1;herbes:10;ail:8;cumin:4;coulis:270;huile:20","Hacher l’oignon et les herbes aussi finement que possible. / Mélanger la viande avec la moitié de l’oignon, les herbes et le cumin. / Former des boulettes allongées et les réserver au frais 10 minutes. / Faire revenir l’ail et le reste d’oignon dans l’huile. / Ajouter le coulis puis les boulettes, couvrir et cuire 18 à 20 minutes. / Vérifier la cuisson complète de la viande et servir avec du riz ou une salade.","🥘","Inspiration libanaise familiale.","liban","");
  add("entree","Taboulé libanais simplifié",20,"froid","herbes:70;menthe:15;tomate:3;oignon:1;semoule:85;citron:2;huile:25","Préparer la semoule selon les instructions de l’emballage et la laisser refroidir rapidement. / Laver et sécher soigneusement les herbes et la menthe. / Hacher très finement les herbes, la menthe et l’oignon. / Couper les tomates en petits dés puis les égoutter légèrement. / Mélanger le tout avec le jus de citron et l’huile. / Réserver au frais jusqu’au service.","🥗","Version simplifiée à la semoule, inspirée du taboulé levantin très riche en persil.","liban","");
  add("plat","Chakchouka aux œufs",35,"poêle","oeuf:4;poivron:2;tomate:4;oignon:1;ail:8;paprika:4;cumin:3;huile:20","Couper les poivrons en lanières et les tomates en morceaux. / Faire revenir oignon et poivrons dans l’huile pendant 8 minutes. / Ajouter ail, paprika et cumin puis mélanger une minute. / Incorporer les tomates et laisser mijoter 12 minutes pour épaissir la sauce. / Former quatre creux et y casser les œufs. / Couvrir et poursuivre la cuisson jusqu’à ce que les blancs soient pris et les jaunes cuits selon les convives.","🍳","Plat présent dans plusieurs traditions culinaires du Maghreb.","maghreb","");
  add("plat","Chorba de lentilles familiale",40,"casserole","lentilles_corail:200;carotte:180;coulis:180;oignon:1;ail:7;cumin:4;bouillon:1;huile:15","Émincer l’oignon, couper les carottes en dés et rincer les lentilles. / Faire revenir l’oignon dans l’huile 4 minutes. / Ajouter ail, cumin, carottes et coulis puis remuer. / Verser lentilles, bouillon et environ 650 ml d’eau. / Couvrir et laisser mijoter 22 à 25 minutes en remuant de temps en temps. / Goûter, ajuster la texture avec un peu d’eau et servir chaud.","🥣","Soupe inspirée des traditions du Maghreb.","maghreb","");

